def validate_square(matrix):
    """
    Ensure the input is a non-empty square two dimensional list of integers.

    Raises ValueError if the structure is not square, or TypeError if any
    element is not an integer.
    """
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of rows")
    size = len(matrix)
    for row in matrix:
        if not isinstance(row, list) or len(row) != size:
            raise ValueError("matrix must be square")
        for value in row:
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError("matrix elements must be integers")
    return size


def transpose(matrix):
    """
    Invert rows into columns.

    Returns a new two dimensional list where element [i][j] of the result is
    element [j][i] of the input.
    """
    return [[row[index] for row in matrix] for index in range(len(matrix))]


def main_diagonal_sum(matrix):
    """
    Sum the top left to bottom right diagonal of a square matrix.
    """
    return sum(matrix[index][index] for index in range(len(matrix)))


def anti_diagonal_sum(matrix):
    """
    Sum the top right to bottom left diagonal of a square matrix.
    """
    size = len(matrix)
    return sum(matrix[index][size - 1 - index] for index in range(size))


def analyze(matrix):
    """
    Break a square matrix down into its transpose and its two traces.

    Returns a tuple of the transposed two dimensional list, the main diagonal
    sum and the anti diagonal sum.
    """
    validate_square(matrix)
    return transpose(matrix), main_diagonal_sum(matrix), anti_diagonal_sum(matrix)


def format_matrix(matrix):
    """
    Render a matrix as aligned rows of right justified integers.
    """
    width = max(len(str(value)) for row in matrix for value in row)
    return "\n".join(" ".join(str(value).rjust(width) for value in row) for row in matrix)


def format_report(matrix):
    """
    Produce a human readable report of the analysis of one matrix.
    """
    transposed, primary, secondary = analyze(matrix)
    lines = ["original:", format_matrix(matrix), "transposed:", format_matrix(transposed)]
    lines.append("main diagonal sum: {0}".format(primary))
    lines.append("anti diagonal sum: {0}".format(secondary))
    return "\n".join(lines)


def main():
    """
    Analyze a couple of sample matrices and print their reports.
    """
    samples = [
        [[1, 2, 3], [4, 5, 6], [7, 8, 9]],
        [[2, -1], [10, 4]],
    ]
    for sample in samples:
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

