def normalize(color):
    """
    Validate an RGB triple and scale each component into the range 0..1.
    """
    if len(color) != 3:
        raise ValueError("color must have exactly three components")
    for component in color:
        if not isinstance(component, int) or not 0 <= component <= 255:
            raise ValueError("components must be integers between 0 and 255")
    return tuple(component / 255.0 for component in color)


def extremes(scaled):
    """
    Return the maximum and minimum of the scaled colour components.
    """
    return max(scaled), min(scaled)


def delta_difference(maximum, minimum):
    """
    Return the spread between the brightest and darkest components.
    """
    return maximum - minimum


def scale_percent(fraction):
    """
    Convert a 0..1 fraction into a rounded whole percentage.
    """
    return int(round(fraction * 100))


def calculate_lightness(maximum, minimum):
    """
    Lightness is the midpoint between the extreme components.
    """
    return (maximum + minimum) / 2.0


def calculate_saturation(maximum, minimum, lightness):
    """
    Saturation of the colour, expressed as a 0..1 fraction.
    """
    delta = delta_difference(maximum, minimum)
    if delta == 0:
        return 0.0
    if lightness > 0.5:
        return delta / (2.0 - maximum - minimum)
    return delta / (maximum + minimum)


def assign_hue(scaled, maximum, delta):
    """
    Pick the hue sector from whichever component is the maximum.
    """
    red, green, blue = scaled
    if maximum == red:
        sector = ((green - blue) / delta) % 6.0
    elif maximum == green:
        sector = (blue - red) / delta + 2.0
    else:
        sector = (red - green) / delta + 4.0
    return sector * 60.0


def calculate_hue(scaled, maximum, minimum):
    """
    Hue in degrees; grey colours have an undefined hue reported as zero.
    """
    delta = delta_difference(maximum, minimum)
    if delta == 0:
        return 0.0
    return assign_hue(scaled, maximum, delta)


def transform(color):
    """
    Convert an (R, G, B) tuple into an (hue, saturation%, lightness%) tuple.
    """
    scaled = normalize(color)
    maximum, minimum = extremes(scaled)
    lightness = calculate_lightness(maximum, minimum)
    saturation = calculate_saturation(maximum, minimum, lightness)
    hue = calculate_hue(scaled, maximum, minimum)
    return int(round(hue)) % 360, scale_percent(saturation), scale_percent(lightness)


def describe(color):
    """
    Build a readable line pairing an RGB triple with its HSL conversion.
    """
    hue, saturation, lightness = transform(color)
    return "rgb{0} -> hsl({1}, {2}%, {3}%)".format(color, hue, saturation, lightness)


def main():
    """
    Report the HSL conversion of a few representative colours.
    """
    samples = [(255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 255),
               (0, 0, 0), (128, 128, 128), (35, 80, 200)]
    for sample in samples:
        print(describe(sample))


if __name__ == "__main__":
    main()

