import math


def validate_point(point):
    """
    Validate that a point is a sequence of exactly three integers.

    Returns the point as a three element tuple of ints, raising
    ValueError or TypeError when the input is malformed.
    """
    values = tuple(point)
    if len(values) != 3:
        raise ValueError("a point must have exactly three coordinates")
    for value in values:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("coordinates must be plain integers")
    return values


def axis_deltas(first, second):
    """
    Produce the absolute differences along the x, y and z axes.
    """
    return tuple(abs(a - b) for a, b in zip(first, second))


def euclidean_distance(first, second):
    """
    Return the straight line distance between two 3D points.

    The distance is the square root of the summed squared axis deltas.
    """
    return math.sqrt(sum(delta * delta for delta in axis_deltas(first, second)))


def manhattan_distance(first, second):
    """
    Return the taxicab distance, the sum of the absolute axis deltas.
    """
    return float(sum(axis_deltas(first, second)))


def chebyshev_distance(first, second):
    """
    Return the largest absolute difference found on any single axis.
    """
    return float(max(axis_deltas(first, second)))


def measure(points):
    """
    Compute the Euclidean, Manhattan and Chebyshev distances.

    `points` holds two tuples of three integers each; the result is a
    tuple of three floats rounded to two decimal places.
    """
    pair = tuple(points)
    if len(pair) != 2:
        raise ValueError("measure expects exactly two points")
    first = validate_point(pair[0])
    second = validate_point(pair[1])
    return (
        round(euclidean_distance(first, second), 2),
        round(manhattan_distance(first, second), 2),
        round(chebyshev_distance(first, second), 2),
    )


def format_report(points):
    """
    Build a human readable one line summary of the three metrics.
    """
    euclid, manhattan, chebyshev = measure(points)
    start, end = tuple(points)
    return (
        "{0} -> {1}: euclidean={2:.2f}, manhattan={3:.2f}, chebyshev={4:.2f}"
        .format(start, end, euclid, manhattan, chebyshev)
    )


def main():
    """
    Print reports for a few sample point pairs.
    """
    samples = [
        ((0, 0, 0), (1, 2, 2)),
        ((-3, 4, 1), (2, -1, 6)),
        ((7, 7, 7), (7, 7, 7)),
    ]
    for pair in samples:
        print(format_report(pair))


if __name__ == "__main__":
    main()

