def _parse(polynomial):
    """
    Split the input into a coefficient list and a value for x.

    The argument pairs the coefficients, ordered from lowest to highest
    degree, with the integer the variable should take.
    """
    coefficients, x = polynomial
    if not coefficients:
        raise ValueError("polynomial must contain at least one coefficient")
    for coefficient in coefficients:
        if not isinstance(coefficient, int) or isinstance(coefficient, bool):
            raise TypeError("coefficients must be plain integers")
    if not isinstance(x, int) or isinstance(x, bool):
        raise TypeError("x must be a plain integer")
    return list(coefficients), x


def derivative(coefficients):
    """
    Apply the power rule once to a coefficient list.

    Each coefficient is multiplied by its index and the resulting list is
    shifted down one degree, so the constant term disappears.
    """
    shifted = []
    for index in range(1, len(coefficients)):
        shifted.append(coefficients[index] * index)
    return shifted


def second_derivative(coefficients):
    """
    Differentiate a coefficient list twice by reusing the power rule.
    """
    return derivative(derivative(coefficients))


def evaluate(coefficients, x):
    """
    Compute the numerical value of the polynomial at the given x.

    Horner's method keeps the arithmetic in integers by walking the
    coefficients from the highest degree down to the constant term.
    """
    total = 0
    for coefficient in reversed(coefficients):
        total = total * x + coefficient
    return total


def resolve(polynomial):
    """
    Evaluate the polynomial at x and differentiate it twice.

    Returns a tuple of the integer value, the first derivative coefficient
    list and the second derivative coefficient list.
    """
    coefficients, x = _parse(polynomial)
    return evaluate(coefficients, x), derivative(coefficients), second_derivative(coefficients)


def format_polynomial(coefficients):
    """
    Render a coefficient list as a readable algebraic expression.
    """
    terms = []
    for index, coefficient in enumerate(coefficients):
        if coefficient == 0:
            continue
        if index == 0:
            terms.append(str(coefficient))
        elif index == 1:
            terms.append("{0}x".format(coefficient))
        else:
            terms.append("{0}x^{1}".format(coefficient, index))
    if not terms:
        return "0"
    return " + ".join(reversed(terms))


def describe(polynomial):
    """
    Build a three-line report for the polynomial at the given x.
    """
    coefficients, x = polynomial
    value, first, second = resolve(polynomial)
    return "\n".join([
        "p(x) = {0}".format(format_polynomial(coefficients)),
        "p({0}) = {1}".format(x, value),
        "p'(x) = {0}, p''(x) = {1}".format(format_polynomial(first), format_polynomial(second)),
    ])


def main():
    print(describe(([1, 2, 3], 2)))
    print(describe(([-4, 0, 0, 5], 3)))


if __name__ == "__main__":
    main()

