DIGITS = set(range(1, 10))


def is_valid_group(group):
    """
    Return True when the nine values form the digits 1..9 exactly once each.
    """
    return len(group) == 9 and set(group) == DIGITS


def check_rows(grid):
    """
    Confirm every horizontal row of the board holds the digits 1..9 once.
    """
    return all(is_valid_group(row) for row in grid)


def check_columns(grid):
    """
    Confirm every vertical column of the board holds the digits 1..9 once.
    """
    return all(is_valid_group([row[index] for row in grid]) for index in range(9))


def check_subgrids(grid):
    """
    Confirm each of the nine 3x3 blocks holds the digits 1..9 once.
    """
    for top in range(0, 9, 3):
        for left in range(0, 9, 3):
            block = [grid[top + dr][left + dc] for dr in range(3) for dc in range(3)]
            if not is_valid_group(block):
                return False
    return True


def has_valid_shape(grid):
    """
    Check that the input really is a nine by nine structure of integers.
    """
    if len(grid) != 9:
        return False
    for row in grid:
        if len(row) != 9 or not all(isinstance(value, int) for value in row):
            return False
    return True


def verify(grid):
    """
    Validate a completed board by testing rows, columns and subgrids.

    Returns True only if all three independent evaluations succeed.
    """
    if not has_valid_shape(grid):
        return False
    return check_rows(grid) and check_columns(grid) and check_subgrids(grid)


def describe(grid):
    """
    Build a human readable report of which segment groups passed or failed.
    """
    results = [
        ("rows", check_rows(grid)),
        ("columns", check_columns(grid)),
        ("subgrids", check_subgrids(grid)),
    ]
    parts = ["%s: %s" % (name, "ok" if passed else "bad") for name, passed in results]
    return " | ".join(parts) + " -> " + str(verify(grid))


def parse_board(lines):
    """
    Turn nine strings of nine digit characters into a grid of integers.
    """
    rows = [line.strip() for line in lines if line.strip()]
    return [[int(character) for character in row] for row in rows]


def main():
    """
    Verify a valid board and a corrupted copy of it, printing both reports.
    """
    board = parse_board([
        "534678912", "672195348", "198342567",
        "859761423", "426853791", "713924856",
        "961537284", "287419635", "345286179",
    ])
    print(describe(board))
    broken = [row[:] for row in board]
    broken[0][0], broken[0][1] = broken[0][1], broken[0][0]
    print(describe(broken))


if __name__ == "__main__":
    main()

