def _line_winner(line):
    """
    Return the mark shared by all three cells of a line, or None.

    A line only counts when every cell holds the same non-space mark.
    """
    first = line[0]
    if first != " " and line[1] == first and line[2] == first:
        return first
    return None


def check_rows(board):
    """
    Scan the three horizontal lines and return the winning mark, if any.
    """
    for row in board:
        winner = _line_winner(row)
        if winner:
            return winner
    return None


def check_columns(board):
    """
    Scan the three vertical lines and return the winning mark, if any.
    """
    for col in range(3):
        winner = _line_winner([board[row][col] for row in range(3)])
        if winner:
            return winner
    return None


def check_diagonals(board):
    """
    Scan both diagonals and return the winning mark, if any.
    """
    diagonals = [
        [board[0][0], board[1][1], board[2][2]],
        [board[0][2], board[1][1], board[2][0]],
    ]
    for diagonal in diagonals:
        winner = _line_winner(diagonal)
        if winner:
            return winner
    return None


def is_full(board):
    """
    Report whether every cell of the board has been played.
    """
    return all(cell != " " for row in board for cell in row)


def validate_board(board):
    """
    Ensure the board is a three by three grid of "X", "O" or " " strings.

    Raises ValueError when the shape or the cell contents are wrong.
    """
    if len(board) != 3 or any(len(row) != 3 for row in board):
        raise ValueError("board must be three rows of three cells")
    for row in board:
        for cell in row:
            if cell not in ("X", "O", " "):
                raise ValueError("cells must be 'X', 'O' or ' '")


def judge(board):
    """
    Decide the state of a tic-tac-toe board.

    Returns the winning mark, "draw" for a full board with no winner,
    or "ongoing" while empty cells remain.
    """
    validate_board(board)
    for check in (check_rows, check_columns, check_diagonals):
        winner = check(board)
        if winner:
            return winner
    return "draw" if is_full(board) else "ongoing"


def render(board):
    """
    Build a human readable picture of the board for reporting.
    """
    return "\n".join("|".join(row) for row in board)


def main():
    """
    Judge a few sample boards and print each grid with its verdict.
    """
    boards = [
        [["X", "X", "X"], ["O", "O", " "], [" ", " ", " "]],
        [["O", "X", "X"], ["X", "O", "O"], ["X", "O", "X"]],
        [["X", "O", "X"], [" ", "O", " "], [" ", "O", " "]],
        [["X", "O", " "], [" ", " ", " "], [" ", " ", " "]],
    ]
    for board in boards:
        print(render(board))
        print("verdict:", judge(board))
        print("-" * 5)


if __name__ == "__main__":
    main()

