FAT_CATEGORY = "fat"
STABILIZER_RATE = 0.005
PREMIUM_THRESHOLD = 0.14
STANDARD_THRESHOLD = 0.10


def validate_ingredients(ingredients):
    """
    Check that the input is a list of (category, grams) pairs.

    Raises ValueError if a pair is malformed or carries a negative weight.
    """
    if not isinstance(ingredients, list):
        raise ValueError("ingredients must be a list of (category, grams) tuples")
    for entry in ingredients:
        if len(entry) != 2:
            raise ValueError("each ingredient needs a category and a weight: %r" % (entry,))
        category, grams = entry
        if not isinstance(category, str):
            raise ValueError("ingredient category must be a string: %r" % (category,))
        if grams < 0:
            raise ValueError("ingredient weight cannot be negative: %r" % (grams,))


def total_fat(ingredients):
    """
    Sum the weight in grams of every ingredient in the fat category.
    """
    return sum(grams for category, grams in ingredients
               if category.strip().lower() == FAT_CATEGORY)


def total_weight(ingredients):
    """
    Sum the weight in grams of the whole ice cream base.
    """
    return sum(grams for _, grams in ingredients)


def stabilizer_weight(base_weight):
    """
    Return the stabilizer needed for the base: 0.5% of the total weight.
    """
    return base_weight * STABILIZER_RATE


def classify_richness(fat, base_weight):
    """
    Label the base by its fat share of the total weight.

    A share above 14% is premium, a share of 10% or more is standard,
    anything lower (including an empty base) is light.
    """
    if base_weight <= 0:
        return "light"
    share = fat / base_weight
    if share > PREMIUM_THRESHOLD:
        return "premium"
    if share >= STANDARD_THRESHOLD:
        return "standard"
    return "light"


def analyze(ingredients):
    """
    Analyze an ice cream base given as (category, grams) tuples.

    Returns a tuple of the required stabilizer weight in grams and the
    richness classification of the base.
    """
    validate_ingredients(ingredients)
    base_weight = total_weight(ingredients)
    fat = total_fat(ingredients)
    return stabilizer_weight(base_weight), classify_richness(fat, base_weight)


def format_report(name, ingredients):
    """
    Build a one-line human readable summary of a named base.
    """
    stabilizer, richness = analyze(ingredients)
    return "%s: %.1f g base, %.2f g stabilizer, %s" % (
        name, total_weight(ingredients), stabilizer, richness)


def main():
    """
    Print reports for a few sample homemade bases.
    """
    bases = {
        "classic custard": [("fat", 100), ("sugar", 150), ("milk solids", 100), ("water", 650)],
        "gelato": [("fat", 60), ("sugar", 180), ("milk solids", 110), ("water", 650)],
        "rich french": [("fat", 180), ("sugar", 160), ("milk solids", 120), ("water", 540)],
    }
    for name in sorted(bases):
        print(format_report(name, bases[name]))


if __name__ == "__main__":
    main()

