CHAMBER_COUNT = 4


def validate(pressures):
    """
    Check that the reading is a sequence of four numeric chamber pressures.

    Raises ValueError for the wrong number of chambers and TypeError for
    readings that are not numbers.
    """
    if len(pressures) != CHAMBER_COUNT:
        raise ValueError("expected %d chamber pressures, got %d" % (CHAMBER_COUNT, len(pressures)))
    for index, value in enumerate(pressures):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("chamber %d reading is not numeric: %r" % (index, value))
    return list(pressures)


def average_pressure(pressures):
    """
    Return the mean pressure across the chambers (diagnostic step one).
    """
    return sum(pressures) / float(len(pressures))


def deviations(pressures, mean):
    """
    Return each chamber's signed deviation from the mean (diagnostic step two).

    A negative deviation means the chamber is below the average and therefore
    under-pressurised.
    """
    return [value - mean for value in pressures]


def adjustment(deviation):
    """
    Translate one deviation into an airflow command (diagnostic step three).

    Chambers below the average are inflated by the full shortfall; chambers
    above the average are deflated by half of the excess.
    """
    if deviation < 0:
        return int(round(-deviation))
    return -int(round(deviation / 2.0))


def balance(pressures):
    """
    Return the airflow adjustment for each chamber, in the original order.
    """
    readings = validate(pressures)
    mean = average_pressure(readings)
    return [adjustment(delta) for delta in deviations(readings, mean)]


def describe(value):
    """
    Render a single adjustment value as a human-readable airflow command.
    """
    if value > 0:
        return "inflate %d" % value
    if value < 0:
        return "deflate %d" % -value
    return "hold"


def format_report(pressures):
    """
    Build a multi-line report pairing each chamber reading with its command.
    """
    commands = balance(pressures)
    mean = average_pressure(validate(pressures))
    lines = ["mean pressure: %.2f" % mean]
    for index, (reading, value) in enumerate(zip(pressures, commands)):
        lines.append("chamber %d: %s -> %s" % (index + 1, reading, describe(value)))
    lines.append("adjustments: %s" % (commands,))
    return "\n".join(lines)


def main():
    """
    Run the balancer on a sample set of chamber readings.
    """
    print(format_report([100, 120, 90, 130]))
    print()
    print(format_report([200, 200, 200, 200]))


if __name__ == "__main__":
    main()

