def average_height(pattern):
    """
    Return the arithmetic mean of the throw heights in a pattern.

    The mean of a siteswap equals the number of objects required to
    juggle it, so it is the first quantity the validator needs.
    """
    return sum(pattern) / len(pattern)


def object_count(pattern):
    """
    Return the number of objects in a pattern, or None.

    None is returned when the average height is not a whole number,
    which already proves the pattern cannot be juggled.
    """
    average = average_height(pattern)
    if average != int(average):
        return None
    return int(average)


def landing_slots(pattern):
    """
    Simulate the landing beat of the throw made on each beat.

    Throw i made on beat i lands on beat (i + pattern[i]), which is
    reduced modulo the period because the pattern repeats forever.
    """
    period = len(pattern)
    return [(beat + height) % period for beat, height in enumerate(pattern)]


def has_collision(pattern):
    """
    Report whether two objects of the pattern land on the same beat.

    A juggleable siteswap sends exactly one object to every beat of
    its period, so duplicated landing slots mean a collision.
    """
    slots = landing_slots(pattern)
    return len(set(slots)) != len(slots)


def is_well_formed(pattern):
    """
    Check that a pattern is usable input for the validator.

    A pattern must be a non-empty sequence of non-negative integers;
    anything else cannot be interpreted as throw heights.
    """
    if not pattern:
        return False
    return all(isinstance(height, int) and height >= 0 for height in pattern)


def validate(patterns):
    """
    Return a list of booleans, one per candidate siteswap pattern.

    A pattern is valid when it is well formed, its average height is
    a whole number, and its simulated landings never collide.
    """
    results = []
    for pattern in patterns:
        if not is_well_formed(pattern):
            results.append(False)
        elif object_count(pattern) is None:
            results.append(False)
        else:
            results.append(not has_collision(pattern))
    return results


def describe(pattern, valid):
    """
    Build a one-line human readable verdict for a single pattern.

    Valid patterns are annotated with the number of objects they need;
    invalid ones state the reason detected during validation.
    """
    text = "".join(str(height) for height in pattern) if pattern else "(empty)"
    if valid:
        return "{0}: juggleable with {1} object(s)".format(text, object_count(pattern))
    if not is_well_formed(pattern):
        return "{0}: malformed throw heights".format(text)
    if object_count(pattern) is None:
        return "{0}: average height {1:.2f} is not a whole number".format(
            text, average_height(pattern))
    return "{0}: two objects land on the same beat".format(text)


def main():
    """
    Validate a sample collection of patterns and print the verdicts.
    """
    patterns = [[4, 4, 1], [3, 2], [3], [5, 3, 1], [4, 4, 4], [7, 5, 3, 1, 0]]
    for pattern, valid in zip(patterns, validate(patterns)):
        print(describe(pattern, valid))


if __name__ == "__main__":
    main()

