def longest_hot_run(readings):
    """
    Return the length of the longest streak of consecutive readings above 8 C.
    """
    best = 0
    current = 0
    for reading in readings:
        if reading > 8:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def has_freeze_event(readings):
    """
    Report whether any single reading dropped below freezing (0 C).
    """
    return any(reading < 0 for reading in readings)


