    """
    Sum the degree-readings accumulated above the 8 C limit over the transit.
    """
    return sum(reading - 8 for reading in readings if reading > 8)


def validate(readings):
    """
    Ensure a shipment is a non-empty sequence of integer temperature readings.
    """
    if not isinstance(readings, (list, tuple)) or not readings:
        raise ValueError("each shipment must be a non-empty list of readings")
    for reading in readings:
        if isinstance(reading, bool) or not isinstance(reading, int):
            raise ValueError("temperature readings must be integers")


