    """
    Classify one shipment, returning its status and the metrics behind it.
    """
    validate(readings)
    run = longest_hot_run(readings)
    frozen = has_freeze_event(readings)
    exposure = heat_exposure(readings)
    compromised = run >= 2 or frozen or exposure > 10
    status = "compromised" if compromised else "safe"
