VOWELS = frozenset("aeiou")


def count_vowels(text):
    """
    Return the number of vowels (a, e, i, o, u) in `text`, ignoring case.
    """
    return sum(1 for character in text.lower() if character in VOWELS)


def vowel_frequencies(text):
    """
    Map each vowel to how many times it occurs in `text`, ignoring case.
    """
    counts = {vowel: 0 for vowel in sorted(VOWELS)}
    for character in text.lower():
        if character in counts:
            counts[character] += 1
    return counts


def count_consonants(text):
    """
    Count the alphabetic characters of `text` that are not vowels.
    """
    return sum(1 for character in text.lower()
               if character.isalpha() and character not in VOWELS)


def vowel_ratio(text):
    """
    Return the share of alphabetic characters in `text` that are vowels.

    Strings without any letters have no meaningful ratio, so 0.0 is returned.
    """
    vowels = count_vowels(text)
    letters = vowels + count_consonants(text)
    if letters == 0:
        return 0.0
    return vowels / letters


def most_common_vowel(text):
    """
    Return the most frequent vowel in `text`, or None if there is none.

    Ties are broken alphabetically so the result is deterministic.
    """
    frequencies = vowel_frequencies(text)
    best = max(sorted(frequencies), key=lambda vowel: frequencies[vowel])
    if frequencies[best] == 0:
        return None
    return best


def normalize(text):
    """
    Coerce `text` to a string, rejecting values that are not text-like.
    """
    if isinstance(text, str):
        return text
    if isinstance(text, (bytes, bytearray)):
        return text.decode("utf-8", errors="ignore")
    raise TypeError("count_vowels expects a string, got %r" % type(text).__name__)


def describe(text):
    """
    Build a one-line human readable summary of the vowels in `text`.
    """
    source = normalize(text)
    breakdown = ", ".join("%s=%d" % item for item in vowel_frequencies(source).items())
    top = most_common_vowel(source) or "-"
    return "%-14r vowels=%d ratio=%.2f top=%s [%s]" % (
        source, count_vowels(source), vowel_ratio(source), top, breakdown)


def main():
    """
    Print vowel reports for a few sample strings.
    """
    for sample in ["Hello World", "Python", "AEIOU aeiou", "rhythm", ""]:
        print(describe(sample))


if __name__ == "__main__":
    main()

