"""Palindrome detection utilities with a small command-line driver."""

import sys


def normalize(text):
    """Return *text* lowercased with all non-alphanumeric characters removed."""
    return "".join(ch.lower() for ch in text if ch.isalnum())


def is_palindrome(text):
    """Return True if *text* reads the same forwards and backwards.

    Case and non-alphanumeric characters (spaces, punctuation) are ignored,
    so 'A man, a plan, a canal: Panama' is considered a palindrome.
    """
    if not isinstance(text, str):
        raise TypeError("is_palindrome() expects a string")
    cleaned = normalize(text)
    return cleaned == cleaned[::-1]


def longest_palindromic_substring(text):
    """Return the longest substring of *text* that is itself a palindrome.

    Comparison uses the same normalization as :func:`is_palindrome`, and the
    returned value is a slice of the original text (punctuation included).
    """
    best = ""
    for start in range(len(text)):
        for end in range(len(text), start, -1):
            candidate = text[start:end]
            if len(candidate) <= len(best):
                break
            if normalize(candidate) and is_palindrome(candidate):
                best = candidate
                break
    return best


def describe(text):
    """Build a one-line human-readable verdict for *text*."""
    verdict = "is" if is_palindrome(text) else "is not"
    return "{0!r} {1} a palindrome".format(text, verdict)


def report(lines):
    """Yield a verdict line for every entry of *lines*, skipping blank ones."""
    for line in lines:
        stripped = line.strip()
        if stripped:
            yield describe(stripped)


def main(argv):
    """Report on command-line arguments, or on standard input if none given."""
    arguments = argv[1:]
    sources = arguments if arguments else sys.stdin
    for line in report(sources):
        print(line)
    if arguments:
        longest = longest_palindromic_substring(" ".join(arguments))
        if longest:
            print("longest palindromic substring: {0!r}".format(longest))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

