"""
Utilities for summing lists of numbers and reporting on them.
"""

import sys


def sum_list(numbers):
    """
    Return the sum of every number in ``numbers`` (0 for an empty list).
    """
    total = 0
    for value in numbers:
        total += value
    return total


def parse_numbers(text):
    """
    Parse whitespace- or comma-separated numbers from ``text`` into a list.

    Integers are kept as ``int`` so that whole-number sums stay exact.
    """
    numbers = []
    for token in text.replace(",", " ").split():
        try:
            numbers.append(int(token))
        except ValueError:
            numbers.append(float(token))
    return numbers


def mean(numbers):
    """
    Return the arithmetic mean of ``numbers``, or ``None`` if empty.
    """
    if not numbers:
        return None
    return sum_list(numbers) / len(numbers)


def running_totals(numbers):
    """
    Return the list of cumulative sums of ``numbers``.
    """
    totals = []
    for index in range(len(numbers)):
        totals.append(sum_list(numbers[:index + 1]))
    return totals


def format_number(value):
    """
    Render ``value`` without a trailing ``.0`` for whole floats.
    """
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe(numbers):
    """
    Build a multi-line report of the sum, mean and running totals.
    """
    lines = ["count: " + str(len(numbers))]
    lines.append("sum:   " + format_number(sum_list(numbers)))
    average = mean(numbers)
    if average is None:
        lines.append("mean:  n/a")
    else:
        lines.append("mean:  " + format_number(round(average, 4)))
    steps = [format_number(total) for total in running_totals(numbers)]
    lines.append("steps: " + (" -> ".join(steps) if steps else "n/a"))
    return "\n".join(lines)


def main(argv):
    """
    Sum the numbers given on the command line, or read them from stdin.
    """
    if len(argv) > 1:
        text = " ".join(argv[1:])
    else:
        text = sys.stdin.read()
    print(describe(parse_numbers(text)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

