import re


def tokenize(sentence):
    """Split a sentence into words, ignoring surrounding punctuation.

    Words are sequences of letters, digits, apostrophes or hyphens, so
    contractions like "don't" and compounds like "well-known" stay intact.
    """
    return re.findall(r"[A-Za-z0-9']+(?:-[A-Za-z0-9']+)*", sentence)


def find_longest_word(sentence):
    """Return the longest word in `sentence`.

    Ties are resolved in favour of the word that appears first. An empty
    string is returned when the sentence contains no words at all.
    """
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    longest = ""
    for word in tokenize(sentence):
        if len(word) > len(longest):
            longest = word
    return longest


def word_lengths(sentence):
    """Pair every word of `sentence` with its length, preserving order."""
    return [(word, len(word)) for word in tokenize(sentence)]


def average_word_length(sentence):
    """Return the mean word length of `sentence`, or 0.0 if it has no words."""
    lengths = [length for _word, length in word_lengths(sentence)]
    if not lengths:
        return 0.0
    return sum(lengths) / len(lengths)


def longest_words(sentence):
    """Return every word of maximum length, in order of appearance."""
    longest = find_longest_word(sentence)
    if not longest:
        return []
    return [word for word in tokenize(sentence) if len(word) == len(longest)]


def describe(sentence):
    """Build a short human-readable report about the words in `sentence`."""
    longest = find_longest_word(sentence)
    if not longest:
        return "no words found"
    tied = longest_words(sentence)
    lines = [
        "sentence: %s" % sentence,
        "longest word: %s (%d letters)" % (longest, len(longest)),
        "average word length: %.2f" % average_word_length(sentence),
    ]
    if len(tied) > 1:
        lines.append("tied with: %s" % ", ".join(tied[1:]))
    return "\n".join(lines)


def main():
    """Report on a few sample sentences."""
    samples = [
        "The quick brown fox",
        "Hello world",
        "She said: don't underestimate well-known counter-examples!",
        "a bb ccc dd e",
        "   ",
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

