        return "no words found"
    tied = longest_words(sentence)
    lines = [
        "sentence: %s" % sentence,
        "longest word: %s (%d letters)" % (longest, len(longest)),
        "average word length: %.2f" % average_word_length(sentence),
    ]
    if len(tied) > 1:
        lines.append("tied with: %s" % ", ".join(tied[1:]))
    return "\n".join(lines)


