import math


def circle_area(radius):
    """Return the area of a circle with the given radius.

    The radius must be a non-negative real number; a ValueError is
    raised otherwise.
    """
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * float(radius) ** 2


def circle_circumference(radius):
    """Return the circumference of a circle with the given radius."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return 2.0 * math.pi * float(radius)


def parse_radius(text):
    """Convert a textual radius into a float.

    Surrounding whitespace is ignored; anything that is not a number
    produces a ValueError describing the offending text.
    """
    stripped = text.strip()
    try:
        return float(stripped)
    except ValueError:
        raise ValueError("not a valid radius: %r" % text)


def format_circle_row(radius):
    """Build a one-line report of the area and circumference."""
    area = circle_area(radius)
    perimeter = circle_circumference(radius)
    return "r=%-8s area=%-20.12g circumference=%.12g" % (radius, area, perimeter)


def annulus_area(inner_radius, outer_radius):
    """Return the area of the ring between two concentric circles.

    The outer radius must be at least as large as the inner one.
    """
    if outer_radius < inner_radius:
        raise ValueError("outer radius must not be smaller than inner radius")
    return circle_area(outer_radius) - circle_area(inner_radius)


def report(texts):
    """Print a table of circle measurements for each textual radius.

    Invalid entries are reported on their own line and skipped, so one
    bad value does not abort the whole table.
    """
    for text in texts:
        try:
            radius = parse_radius(text)
            print(format_circle_row(radius))
        except ValueError as error:
            print("skipping %r: %s" % (text, error))


def main():
    """Run the report on a few radii and show one annulus area."""
    samples = ["1", "0", " 2.5 ", "10", "abc", "-3"]
    report(samples)
    ring = annulus_area(1.0, 2.0)
    print("annulus area between r=1 and r=2: %.12g" % ring)


if __name__ == "__main__":
    main()

