def _validate_measurements(weight_kg, height_m):
    """Check that weight and height are usable positive numbers.

    Raises TypeError for non-numeric input and ValueError for values that
    are zero or negative, since neither can describe a real person.
    """
    for name, value in (("weight_kg", weight_kg), ("height_m", height_m)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be a number, got {type(value).__name__}")
        if value <= 0:
            raise ValueError(f"{name} must be positive, got {value}")


def calculate_bmi(weight_kg, height_m):
    """Return the Body Mass Index for a weight in kg and a height in metres.

    The index is weight divided by the square of the height, rounded to two
    decimal places: calculate_bmi(70, 1.75) -> 22.86.
    """
    _validate_measurements(weight_kg, height_m)
    return round(weight_kg / height_m ** 2, 2)


def classify_bmi(bmi):
    """Map a BMI value to its standard World Health Organization category.

    The thresholds are 18.5, 25 and 30; values at or above 30 are obese.
    """
    if bmi < 18.5:
        return "underweight"
    if bmi < 25.0:
        return "normal weight"
    if bmi < 30.0:
        return "overweight"
    return "obese"


def healthy_weight_range(height_m):
    """Return the (min, max) weight in kg giving a normal BMI at this height.

    The bounds correspond to BMI 18.5 and BMI 24.9 inclusive.
    """
    _validate_measurements(1.0, height_m)
    lower = 18.5 * height_m ** 2
    upper = 24.9 * height_m ** 2
    return round(lower, 1), round(upper, 1)


def describe(weight_kg, height_m):
    """Build a one-line human readable summary for a single measurement.

    The line pairs the BMI with its category and the healthy weight range.
    """
    bmi = calculate_bmi(weight_kg, height_m)
    low, high = healthy_weight_range(height_m)
    return (
        f"{weight_kg} kg at {height_m} m -> BMI {bmi:.2f} ({classify_bmi(bmi)}); "
        f"healthy range {low}-{high} kg"
    )


def report(measurements):
    """Return summary lines for a sequence of (weight, height) pairs.

    Invalid pairs are reported instead of aborting the whole report.
    """
    lines = []
    for weight_kg, height_m in measurements:
        try:
            lines.append(describe(weight_kg, height_m))
        except (TypeError, ValueError) as error:
            lines.append(f"{weight_kg!r}/{height_m!r} -> invalid: {error}")
    return lines


def main():
    """Print a BMI report for a few sample people.

    The last sample has an impossible height and shows the error handling.
    """
    samples = [
        (70, 1.75),
        (100, 2.0),
        (52, 1.68),
        (95, 1.70),
        (80, 0),
    ]
    for line in report(samples):
        print(line)


if __name__ == "__main__":
    main()

