import math


def distance_2d(x1, y1, x2, y2):
    """Return the Euclidean distance between (x1, y1) and (x2, y2).

    >>> distance_2d(0, 0, 3, 4)
    5.0
    """
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def parse_point(text):
    """Parse a point written as "x,y" and return it as a tuple of floats.

    Raises ValueError if the text does not hold exactly two numbers.
    """
    parts = text.split(",")
    if len(parts) != 2:
        raise ValueError("expected two comma-separated numbers: %r" % text)
    return float(parts[0]), float(parts[1])


def path_length(points):
    """Return the total length of the polyline through the given points."""
    total = 0.0
    for (x1, y1), (x2, y2) in zip(points, points[1:]):
        total += distance_2d(x1, y1, x2, y2)
    return total


def nearest_pair(points):
    """Return the two closest points and their distance.

    The result is a tuple (first, second, distance). At least two points
    are required.
    """
    if len(points) < 2:
        raise ValueError("need at least two points")
    best = None
    for i, (x1, y1) in enumerate(points):
        for x2, y2 in points[i + 1:]:
            gap = distance_2d(x1, y1, x2, y2)
            if best is None or gap < best[2]:
                best = ((x1, y1), (x2, y2), gap)
    return best


def format_point(point):
    """Format a point as "(x, y)" with three decimal places."""
    return "(%.3f, %.3f)" % point


def report(texts):
    """Build a human-readable report about the points given as strings."""
    points = [parse_point(t) for t in texts]
    lines = ["Points: " + " ".join(format_point(p) for p in points)]
    for (a, b) in zip(points, points[1:]):
        lines.append(
            "%s -> %s : %.4f" % (format_point(a), format_point(b),
                                 distance_2d(a[0], a[1], b[0], b[1]))
        )
    lines.append("Path length: %.4f" % path_length(points))
    first, second, gap = nearest_pair(points)
    lines.append("Closest: %s and %s at %.4f"
                 % (format_point(first), format_point(second), gap))
    return "\n".join(lines)


def main():
    """Print distances for a small sample of points."""
    print(distance_2d(0, 0, 3, 4))
    print(distance_2d(1, 1, 1, 1))
    print(report(["0,0", "3,4", "3,5", "-2,1"]))


if __name__ == "__main__":
    main()

