def validate_count(n):
    """Return `n` coerced to a non-negative integer.

    Accepts integers or strings of digits; raises ValueError for anything
    that cannot describe a count of terms.
    """
    if isinstance(n, bool) or not isinstance(n, (int, str)):
        raise ValueError("count must be an integer, got %r" % (n,))
    value = int(n)
    if value < 0:
        raise ValueError("count must be non-negative, got %d" % value)
    return value


def list_of_squares(n):
    """Return the squares of 1..n inclusive as a list.

    list_of_squares(3) -> [1, 4, 9] and list_of_squares(0) -> [].
    """
    count = validate_count(n)
    return [i * i for i in range(1, count + 1)]


def sum_of_squares(n):
    """Return the sum of the squares of 1..n inclusive."""
    return sum(list_of_squares(n))


def closed_form_sum(n):
    """Return n(n+1)(2n+1)/6, the closed form for the sum of squares."""
    count = validate_count(n)
    return count * (count + 1) * (2 * count + 1) // 6


def format_row(index, square, running_total):
    """Format one aligned table row for a single square."""
    return "{:>4} {:>8} {:>10}".format(index, square, running_total)


def format_table(n):
    """Return a multi-line table of the squares of 1..n with running totals.

    The table always has a header; an empty range produces a note instead
    of any data rows.
    """
    lines = [format_row("n", "n^2", "sum")]
    squares = list_of_squares(n)
    if not squares:
        lines.append("(no terms)")
        return "\n".join(lines)
    running = 0
    for index, square in enumerate(squares, start=1):
        running += square
        lines.append(format_row(index, square, running))
    return "\n".join(lines)


def main(argv):
    """Print the squares table for each count given on the command line."""
    requests = argv[1:] or ["3", "0", "10"]
    for request in requests:
        try:
            count = validate_count(request)
        except ValueError as error:
            print("skipping %r: %s" % (request, error))
            continue
        print("squares up to %d: %s" % (count, list_of_squares(count)))
        print(format_table(count))
        print("total = %d (closed form %d)"
              % (sum_of_squares(count), closed_form_sum(count)))
        print()
    return 0


if __name__ == "__main__":
    import sys

    sys.exit(main(sys.argv))

