import random
import string

ALPHABET = string.ascii_lowercase + string.ascii_uppercase + string.digits


def validate_length(length):
    """Return `length` as an int, raising ValueError if it is not a usable size.

    Passwords must have at least one character, and the value has to be a
    whole number, so floats like 8.5 and negative sizes are rejected.
    """
    if isinstance(length, bool) or not isinstance(length, int):
        raise ValueError("length must be an integer, got %r" % (length,))
    if length < 1:
        raise ValueError("length must be at least 1, got %d" % length)
    return length


def generate_password(length):
    """Build a random password of exactly `length` characters.

    Characters are drawn independently with `random.choice` from the pool of
    lowercase letters, uppercase letters and digits.
    """
    length = validate_length(length)
    return "".join(random.choice(ALPHABET) for _ in range(length))


def character_counts(password):
    """Count how many lowercase, uppercase and digit characters `password` has."""
    return {
        "lower": sum(1 for c in password if c in string.ascii_lowercase),
        "upper": sum(1 for c in password if c in string.ascii_uppercase),
        "digit": sum(1 for c in password if c in string.digits),
    }


def classify(password):
    """Describe the variety of a password as 'weak', 'fair' or 'strong'.

    The rating combines the number of distinct character classes present with
    the overall length of the password.
    """
    counts = character_counts(password)
    classes = sum(1 for value in counts.values() if value > 0)
    if len(password) < 8 or classes == 1:
        return "weak"
    if classes == 2 or len(password) < 12:
        return "fair"
    return "strong"


def format_report(password):
    """Render one password and its statistics as a single printable line."""
    counts = character_counts(password)
    return "{0:<16} len={1:<3} lower={2} upper={3} digit={4} -> {5}".format(
        password,
        len(password),
        counts["lower"],
        counts["upper"],
        counts["digit"],
        classify(password),
    )


def main():
    """Generate a few sample passwords of different sizes and report on them."""
    for size in (4, 8, 12, 16):
        print(format_report(generate_password(size)))
    try:
        generate_password(0)
    except ValueError as error:
        print("rejected:", error)


if __name__ == "__main__":
    main()

