def sum_digits(n):
    """
    Return the sum of the decimal digits of the non-negative integer n.

    Raises TypeError if n is not an integer and ValueError if n is negative.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    total = 0
    while n:
        n, digit = divmod(n, 10)
        total += digit
    return total


def digital_root(n):
    """
    Repeatedly sum the digits of n until a single digit remains.
    """
    value = sum_digits(n)
    while value > 9:
        value = sum_digits(value)
    return value


def is_harshad(n):
    """
    Tell whether n is divisible by the sum of its own digits.
    """
    total = sum_digits(n)
    if total == 0:
        return False
    return n % total == 0


def parse_number(text):
    """
    Convert a user-supplied string into a non-negative integer.

    Surrounding whitespace and underscores used as digit separators are
    ignored, so both "1234" and "1_234" are accepted.
    """
    cleaned = text.strip().replace("_", "")
    if not cleaned.isdigit():
        raise ValueError("not a non-negative integer: %r" % (text,))
    return int(cleaned)


