def sort_dict_by_value(d):
    """Return the items of ``d`` as a list of tuples sorted by value ascending.

    The original mapping is left untouched; ties keep their insertion order
    because :func:`sorted` is stable.
    """
    validate_mapping(d)
    return sorted(d.items(), key=lambda item: item[1])


def validate_mapping(d):
    """Raise ``TypeError`` unless ``d`` is a mapping with mutually comparable values."""
    if not isinstance(d, dict):
        raise TypeError("expected a dict, got %s" % type(d).__name__)
    value_types = {type(value) for value in d.values()}
    if len(value_types) > 1 and not value_types <= {int, float}:
        names = ", ".join(sorted(t.__name__ for t in value_types))
        raise TypeError("values are not mutually comparable: %s" % names)


def sort_dict_by_value_desc(d):
    """Return the items of ``d`` sorted by value in descending order."""
    return list(reversed(sort_dict_by_value(d)))


def rank_keys(d):
    """Map every key of ``d`` to its 1-based rank when ordered by value ascending.

    Keys sharing the same value share the same rank, and the rank after a tie
    skips ahead, so ranks always reflect how many entries are strictly smaller.
    """
    ranks = {}
    previous_value = None
    previous_rank = 0
    for position, (key, value) in enumerate(sort_dict_by_value(d), start=1):
        if value == previous_value:
            ranks[key] = previous_rank
        else:
            ranks[key] = position
            previous_rank = position
            previous_value = value
    return ranks


def format_pairs(pairs):
    """Render a list of ``(key, value)`` tuples as aligned ``key: value`` lines."""
    if not pairs:
        return "(empty)"
    width = max(len(str(key)) for key, _ in pairs)
    return "\n".join("%-*s : %s" % (width, key, value) for key, value in pairs)


def report(d):
    """Build a multi-line report of ``d`` sorted ascending, descending and by rank."""
    ascending = sort_dict_by_value(d)
    lines = ["ascending:", format_pairs(ascending)]
    lines += ["descending:", format_pairs(sort_dict_by_value_desc(d))]
    lines += ["ranks:", format_pairs(sorted(rank_keys(d).items()))]
    return "\n".join(lines)


def main():
    """Print reports for a few sample dictionaries, including an empty one."""
    samples = [
        {'a': 3, 'b': 1, 'c': 2},
        {'apple': 5, 'banana': 5, 'cherry': 2, 'date': 9},
        {},
    ]
    for sample in samples:
        print(report(sample))
        print("-" * 32)
    print(sort_dict_by_value({'a': 3, 'b': 1, 'c': 2}))
    print(sort_dict_by_value({}))


if __name__ == "__main__":
    main()

