BEATS = {"rock": "scissors", "paper": "rock", "scissors": "paper"}


def normalize_choice(choice):
    """Return the canonical lowercase name of a Rock-Paper-Scissors choice.

    Raises ValueError if the value is not one of 'rock', 'paper' or
    'scissors' (case and surrounding whitespace are ignored).
    """
    if not isinstance(choice, str):
        raise ValueError("choice must be a string, got %r" % (choice,))
    cleaned = choice.strip().lower()
    if cleaned not in BEATS:
        raise ValueError("invalid choice: %r" % (choice,))
    return cleaned


def rock_paper_scissors(player1_choice, player2_choice):
    """Play one round and report the outcome as a sentence.

    Returns 'Player 1 wins!', 'Player 2 wins!' or "It's a tie!".
    """
    first = normalize_choice(player1_choice)
    second = normalize_choice(player2_choice)
    if first == second:
        return "It's a tie!"
    if BEATS[first] == second:
        return "Player 1 wins!"
    return "Player 2 wins!"


def play_series(rounds):
    """Play every (player1, player2) pair in `rounds` and tally the results.

    Returns a tuple of (results, tally) where results is the list of
    outcome sentences and tally maps each sentence to how often it occurred.
    """
    results = []
    tally = {"Player 1 wins!": 0, "Player 2 wins!": 0, "It's a tie!": 0}
    for p1, p2 in rounds:
        outcome = rock_paper_scissors(p1, p2)
        results.append(outcome)
        tally[outcome] += 1
    return results, tally


def format_round(index, player1_choice, player2_choice, outcome):
    """Render a single round as an aligned, human-readable line.

    The choices are normalized so the report shows canonical names.
    """
    return "Round {0}: {1:>8} vs {2:<8} -> {3}".format(
        index, normalize_choice(player1_choice), normalize_choice(player2_choice), outcome
    )


def format_summary(tally):
    """Summarise a tally produced by play_series into one report line.

    The counts appear in the order: player 1 wins, player 2 wins, ties.
    """
    return "Summary: P1 {0}, P2 {1}, ties {2}".format(
        tally["Player 1 wins!"], tally["Player 2 wins!"], tally["It's a tie!"]
    )


def main():
    """Play a short series of rounds and print the round-by-round report.

    Invalid input is reported instead of crashing the program.
    """
    rounds = [
        ("rock", "scissors"),
        ("paper", "rock"),
        ("Scissors", "rock"),
        ("paper", " paper "),
        ("rock", "paper"),
    ]
    results, tally = play_series(rounds)
    for number, (pair, outcome) in enumerate(zip(rounds, results), start=1):
        print(format_round(number, pair[0], pair[1], outcome))
    print(format_summary(tally))
    try:
        print(rock_paper_scissors("lizard", "rock"))
    except ValueError as error:
        print("Rejected input:", error)


if __name__ == "__main__":
    main()

