def validate_binary(binary_string):
    """Check that the given value is a non-empty string of only '0' and '1'.

    Raises a TypeError for non-string input and a ValueError for any string
    that is empty or contains characters other than '0' and '1'.
    """
    if not isinstance(binary_string, str):
        raise TypeError("binary_string must be a str, got %s" % type(binary_string).__name__)
    stripped = binary_string.strip()
    if not stripped:
        raise ValueError("binary_string must not be empty")
    for position, character in enumerate(stripped):
        if character not in "01":
            raise ValueError("invalid binary digit %r at position %d" % (character, position))
    return stripped


def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' to its decimal value 11.

    Surrounding whitespace is ignored. The digits are folded from the most
    significant end, doubling the accumulated value for each new digit.
    """
    digits = validate_binary(binary_string)
    value = 0
    for character in digits:
        value = value * 2 + (1 if character == "1" else 0)
    return value


def decimal_to_binary(number):
    """Return the shortest binary string whose value is the given integer.

    The number must be non-negative; zero maps to the single digit '0'.
    """
    if number < 0:
        raise ValueError("only non-negative integers have a plain binary form")
    if number == 0:
        return "0"
    digits = []
    while number:
        digits.append("1" if number & 1 else "0")
        number >>= 1
    return "".join(reversed(digits))


def group_bits(binary_string, size=4):
    """Pad a binary string on the left and split it into groups of `size` bits.

    The grouped form ('0000 1011') makes long inputs easier to read in the
    report produced by `main`.
    """
    digits = validate_binary(binary_string)
    padding = (-len(digits)) % size
    padded = "0" * padding + digits
    return " ".join(padded[i:i + size] for i in range(0, len(padded), size))


def describe(binary_string):
    """Build a one-line report of a conversion.

    Invalid inputs are reported through the message of the raised exception
    instead of propagating the error to the caller.
    """
    try:
        value = binary_to_decimal(binary_string)
    except (TypeError, ValueError) as error:
        return "%r -> error: %s" % (binary_string, error)
    return "%s -> %d (round trip: %s)" % (group_bits(binary_string), value, decimal_to_binary(value))


def main():
    """Print conversion reports for a handful of sample inputs.

    Both valid binary strings and rejected values are included so the
    reporting path is exercised end to end.
    """
    samples = ["1011", "1", "0", " 11111111 ", "100000000000", "", "10201", 1011]
    for sample in samples:
        print(describe(sample))


if __name__ == "__main__":
    main()

