import math


def parse_numbers(text):
    """Parse a whitespace- or comma-separated string into a list of floats.

    Raises ValueError if any token is not a valid number.
    """
    tokens = text.replace(",", " ").split()
    return [float(token) for token in tokens]


def calculate_mean(numbers):
    """
    Return the arithmetic mean of a non-empty sequence of numbers.
    """
    return sum(numbers) / len(numbers)


def calculate_variance(numbers):
    """
    Return the sample variance, using the Bessel-corrected n-1 denominator.
    """
    mean = calculate_mean(numbers)
    squared_deviations = [(value - mean) ** 2 for value in numbers]
    return sum(squared_deviations) / (len(numbers) - 1)


def calculate_std_dev(numbers):
    """
    Return the sample standard deviation of a list of numbers.

    At least two numbers must be provided.
    """
    if len(numbers) < 2:
        raise ValueError("at least two numbers are required")
    return math.sqrt(calculate_variance(numbers))


def describe(numbers):
    """
    Build a dictionary of summary statistics for the given numbers.
    """
    ordered = sorted(numbers)
    return {
        "count": len(ordered),
        "min": ordered[0],
        "max": ordered[-1],
        "mean": calculate_mean(ordered),
        "std_dev": calculate_std_dev(ordered),
    }


def format_report(label, numbers):
    """
    Render the summary statistics of a sample as an aligned text block.
    """
    stats = describe(numbers)
    lines = ["{}: {} values".format(label, stats["count"])]
    for key in ("min", "max", "mean", "std_dev"):
        lines.append("  {:<8}{:.3f}".format(key, stats[key]))
    return "\n".join(lines)


def main():
    """
    Report statistics for a few built-in samples, then for user input.
    """
    samples = {
        "ramp": [1, 2, 3, 4, 5],
        "constant": [10, 10, 10],
        "mixed": [2.5, -1.0, 7.25, 3.75],
    }
    for label in sorted(samples):
        print(format_report(label, samples[label]))

    try:
        text = input("Enter at least two numbers: ")
    except EOFError:
        return
    try:
        print(format_report("input", parse_numbers(text)))
    except (ValueError, IndexError) as error:
        print("Could not summarize input: {}".format(error))


if __name__ == "__main__":
    main()

