def validate_sequence(numbers):
    """
    Check that `numbers` can be a 1..N sequence with exactly one gap.

    Returns N, the upper bound of the complete range. Raises TypeError for
    non-integer entries and ValueError when the input is empty, contains
    duplicates, or holds values outside 1..N.
    """
    if not numbers:
        raise ValueError("at least one number is required")
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("all entries must be integers, got %r" % (value,))
    upper = len(numbers) + 1
    if len(set(numbers)) != len(numbers):
        raise ValueError("entries must be unique")
    for value in numbers:
        if value < 1 or value > upper:
            raise ValueError("entry %d is outside the range 1..%d" % (value, upper))
    return upper


def find_missing_number(numbers):
    """
    Return the single number missing from an unsorted 1..N list.

    The expected sum of 1..N is compared with the actual sum, so the result
    does not depend on the ordering of `numbers`.
    """
    upper = validate_sequence(numbers)
    expected = upper * (upper + 1) // 2
    return expected - sum(numbers)


def missing_by_xor(numbers):
    """
    Return the missing number using an XOR fold instead of a sum.

    Every present value cancels with its counterpart from the full 1..N
    range, leaving only the absent one.
    """
    upper = validate_sequence(numbers)
    accumulator = 0
    for value in range(1, upper + 1):
        accumulator ^= value
    for value in numbers:
        accumulator ^= value
    return accumulator


def describe(numbers):
    """
    Build a one-line human readable report for a single input list.

    The sum-based and XOR-based results must agree; a mismatch signals a bug
    in one of the two strategies.
    """
    missing = find_missing_number(numbers)
    checked = missing_by_xor(numbers)
    if missing != checked:
        raise AssertionError("sum and xor disagree: %d vs %d" % (missing, checked))
    shown = ", ".join(str(value) for value in numbers)
    return "[%s] -> missing %d (of 1..%d)" % (shown, missing, len(numbers) + 1)


def main():
    """
    Report the missing number for several sample lists.

    Valid lists are described one per line; malformed inputs are reported
    together with the reason they were rejected.
    """
    for sample in ([1, 2, 4, 5], [5, 1, 3, 2], [2], [7, 3, 1, 6, 5, 2, 8, 9, 10, 11]):
        print(describe(sample))
    for bad in ([], [1, 1, 3], [1, 2, 9]):
        try:
            print(describe(bad))
        except (ValueError, TypeError) as error:
            print("rejected %r: %s" % (bad, error))


if __name__ == "__main__":
    main()

