"""Utilities for joining list elements into a single string."""


def validate_items(items):
    """Return ``items`` as a list of strings, raising ``TypeError`` if invalid."""
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list of strings")
    checked = list(items)
    for element in checked:
        if not isinstance(element, str):
            raise TypeError("every element of items must be a string")
    return checked


def validate_separator(separator):
    """Return ``separator`` unchanged, raising ``TypeError`` if it is not a string."""
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    return separator


def join_elements(items, separator):
    """Join every element of ``items`` into one string, glued by ``separator``.

    >>> join_elements(['apple', 'banana', 'cherry'], ', ')
    'apple, banana, cherry'
    >>> join_elements(['a', 'b'], '-')
    'a-b'
    """
    elements = validate_items(items)
    glue = validate_separator(separator)
    return glue.join(elements)


def join_stripped(items, separator):
    """Join ``items`` after trimming surrounding whitespace from each element."""
    elements = [element.strip() for element in validate_items(items)]
    return join_elements(elements, separator)


def split_elements(joined_string, separator):
    """Split ``joined_string`` back into the list of elements it was built from."""
    glue = validate_separator(separator)
    if not glue:
        raise ValueError("cannot split on an empty separator")
    if not joined_string:
        return []
    return joined_string.split(glue)


def describe_join(items, separator):
    """Build a human readable report about joining ``items`` with ``separator``."""
    result = join_elements(items, separator)
    count = len(validate_items(items))
    return "{0} element(s) joined with {1!r} -> {2!r}".format(count, separator, result)


def main():
    """Demonstrate the joining helpers on a few sample inputs."""
    samples = [
        (['apple', 'banana', 'cherry'], ', '),
        (['a', 'b'], '-'),
        ([], '+'),
        (['solo'], '|'),
    ]
    for items, separator in samples:
        print(describe_join(items, separator))

    messy = ['  red ', 'green  ', ' blue']
    tidy = join_stripped(messy, ';')
    print("tidied:", tidy)
    print("round trip:", split_elements(tidy, ';'))


if __name__ == "__main__":
    main()

