def digits_of(number):
    """Return the decimal digits of a non-negative integer as a list of ints."""
    if number == 0:
        return [0]
    digits = []
    while number > 0:
        digits.append(number % 10)
        number //= 10
    digits.reverse()
    return digits


def _validate(number):
    """Ensure the input is a positive integer, raising ValueError otherwise."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise ValueError("number must be an int, got %r" % (number,))
    if number < 1:
        raise ValueError("number must be positive, got %d" % number)
    return number


def digit_power_sum(number):
    """Sum each digit of `number` raised to the count of its digits."""
    digits = digits_of(number)
    exponent = len(digits)
    return sum(digit ** exponent for digit in digits)


def is_armstrong(number):
    """Return True when `number` equals the sum of its digits raised to the digit count."""
    _validate(number)
    return digit_power_sum(number) == number


def armstrong_numbers_up_to(limit):
    """List every Armstrong number from 1 through `limit` inclusive."""
    _validate(limit)
    return [candidate for candidate in range(1, limit + 1) if is_armstrong(candidate)]


def explain(number):
    """Build a human readable equation showing the digit-power expansion of `number`."""
    digits = digits_of(_validate(number))
    exponent = len(digits)
    terms = " + ".join("%d^%d" % (digit, exponent) for digit in digits)
    values = " + ".join(str(digit ** exponent) for digit in digits)
    total = digit_power_sum(number)
    relation = "==" if total == number else "!="
    return "%s = %s = %d %s %d" % (terms, values, total, relation, number)


def main():
    """Report Armstrong classification for sample numbers and list those below 1000."""
    for sample in (153, 123, 9474, 9475):
        verdict = "Armstrong" if is_armstrong(sample) else "not Armstrong"
        print("%d is %s: %s" % (sample, verdict, explain(sample)))
    print("Armstrong numbers up to 1000:", armstrong_numbers_up_to(1000))
    try:
        is_armstrong(-5)
    except ValueError as error:
        print("rejected input:", error)


if __name__ == "__main__":
    main()

