ABSOLUTE_ZERO_F = -459.67


def fahrenheit_to_celsius(fahrenheit):
    """Convert a Fahrenheit temperature to Celsius and return it as a float."""
    return (float(fahrenheit) - 32.0) * 5.0 / 9.0


def parse_temperature(text):
    """Read a Fahrenheit value from text, accepting an optional trailing 'F'."""
    cleaned = text.strip().rstrip("fF").strip().rstrip("\u00b0").strip()
    if not cleaned:
        raise ValueError("no temperature found in %r" % text)
    return float(cleaned)


def validate_fahrenheit(fahrenheit):
    """Return the value unchanged, or raise ValueError if it is below absolute zero."""
    value = float(fahrenheit)
    if value < ABSOLUTE_ZERO_F:
        raise ValueError("%.2f F is below absolute zero" % value)
    return value


def celsius_to_kelvin(celsius):
    """Convert a Celsius temperature to the Kelvin scale."""
    return celsius + 273.15


def water_state(celsius):
    """Describe the phase of pure water at sea level for the given Celsius value."""
    if celsius <= 0.0:
        return "ice"
    if celsius >= 100.0:
        return "steam"
    return "liquid"


def format_conversion(fahrenheit):
    """Build a one-line report of a Fahrenheit reading in Celsius and Kelvin."""
    value = validate_fahrenheit(fahrenheit)
    celsius = fahrenheit_to_celsius(value)
    return "%8.2f F = %8.2f C = %8.2f K  (%s)" % (
        value,
        celsius,
        celsius_to_kelvin(celsius),
        water_state(celsius),
    )


def convert_all(readings):
    """Convert a sequence of textual Fahrenheit readings into report lines."""
    lines = []
    for reading in readings:
        try:
            lines.append(format_conversion(parse_temperature(reading)))
        except ValueError as error:
            lines.append("%8s -> error: %s" % (reading.strip(), error))
    return lines


def main():
    """Print a small conversion table for a few sample readings."""
    readings = ["32", "212 F", "98.6°F", "-40", "-500", "warm"]
    for line in convert_all(readings):
        print(line)
    print("freezing point:", fahrenheit_to_celsius(32))
    print("boiling point:", fahrenheit_to_celsius(212))


if __name__ == "__main__":
    main()

