import sys


def _build_lookup(values):
    """
    Split ``values`` into a set of hashable members and a list of the rest.

    Sets give constant-time membership tests, but lists may contain
    unhashable items (dicts, lists, ...), which must be compared directly.
    """
    hashable = set()
    unhashable = []
    for value in values:
        try:
            hashable.add(value)
        except TypeError:
            unhashable.append(value)
    return hashable, unhashable


def _is_member(item, hashable, unhashable):
    """
    Report whether ``item`` occurs in either part of a lookup structure.
    """
    try:
        return item in hashable
    except TypeError:
        return any(item == other for other in unhashable)


def list_difference(list1, list2):
    """
    Return the elements of ``list1`` that do not appear in ``list2``.

    The original order and any duplicates of ``list1`` are preserved, so
    ``list_difference([1, 2, 3, 4], [3, 4, 5, 6])`` returns ``[1, 2]``.
    """
    hashable, unhashable = _build_lookup(list2)
    difference_list = []
    for item in list1:
        if not _is_member(item, hashable, unhashable):
            difference_list.append(item)
    return difference_list


def parse_list(text):
    """
    Turn a comma-separated command line argument into a list of values.

    Tokens that look like numbers become ``int`` or ``float``; everything
    else is kept as a trimmed string. Empty input yields an empty list.
    """
    items = []
    for token in text.split(","):
        token = token.strip()
        if not token:
            continue
        for converter in (int, float):
            try:
                items.append(converter(token))
                break
            except ValueError:
                pass
        else:
            items.append(token)
    return items


def format_report(list1, list2, difference_list):
    """
    Build a short human readable summary of one difference computation.
    """
    lines = [
        "first list : {!r}".format(list1),
        "second list: {!r}".format(list2),
        "difference : {!r}".format(difference_list),
        "removed    : {} of {} element(s)".format(
            len(list1) - len(difference_list), len(list1)
        ),
    ]
    return "\n".join(lines)


def main(argv):
    """
    Read two comma-separated lists from ``argv`` and print their difference.
    """
    if len(argv) != 2:
        print("usage: list_difference.py A,B,C X,Y,Z", file=sys.stderr)
        return 1
    list1 = parse_list(argv[0])
    list2 = parse_list(argv[1])
    print(format_report(list1, list2, list_difference(list1, list2)))
