"""Rectangle geometry helpers: area, perimeter and simple report formatting."""

import sys


def parse_dimension(text):
    """Convert a textual dimension into a float, rejecting malformed input."""
    try:
        return float(text)
    except ValueError:
        raise ValueError("dimension %r is not a number" % (text,))


def validate_dimension(value, name):
    """Return value as a float, ensuring it is a positive, finite measurement."""
    number = float(value)
    if number != number or number in (float("inf"), float("-inf")):
        raise ValueError("%s must be a finite number" % name)
    if number <= 0:
        raise ValueError("%s must be positive, got %r" % (name, number))
    return number


def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    w = validate_dimension(width, "width")
    h = validate_dimension(height, "height")
    return w * h


def rectangle_perimeter(width, height):
    """Return the perimeter of a rectangle with the given width and height."""
    w = validate_dimension(width, "width")
    h = validate_dimension(height, "height")
    return 2.0 * (w + h)


def is_square(width, height, tolerance=1e-9):
    """Tell whether the two sides are equal within the given tolerance."""
    w = validate_dimension(width, "width")
    h = validate_dimension(height, "height")
    return abs(w - h) <= tolerance


def describe(width, height):
    """Build a one-line human-readable summary of a rectangle's measurements."""
    area = rectangle_area(width, height)
    perimeter = rectangle_perimeter(width, height)
    shape = "square" if is_square(width, height) else "rectangle"
    return "%s %g x %g -> area %.2f, perimeter %.2f" % (
        shape, float(width), float(height), area, perimeter)


def main(argv):
    """Report a rectangle given on the command line, or run the built-in cases."""
    if len(argv) == 2:
        width = parse_dimension(argv[0])
        height = parse_dimension(argv[1])
        print(describe(width, height))
        return 0
    if argv:
        print("usage: rectangle.py WIDTH HEIGHT", file=sys.stderr)
        return 2
    for width, height in ((5, 10), (2.5, 4), (3, 3)):
        print(describe(width, height))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

