"""Compute the number of days between the Unix epoch and a given date."""

EPOCH_YEAR = 1970
MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def is_leap_year(year):
    """Return True if `year` is a leap year in the proleptic Gregorian calendar."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    """Return the number of days in `month` (1-12) of `year`."""
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def days_in_year(year):
    """Return 366 for leap years and 365 otherwise."""
    return 366 if is_leap_year(year) else 365


def parse_date(date_str):
    """Split a 'YYYY-MM-DD' string into an (year, month, day) tuple of ints.

    Raises ValueError if the layout is wrong or the date does not exist.
    """
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError("expected a date in 'YYYY-MM-DD' format: %r" % (date_str,))
    if len(parts[0]) != 4 or len(parts[1]) != 2 or len(parts[2]) != 2:
        raise ValueError("expected a date in 'YYYY-MM-DD' format: %r" % (date_str,))
    year, month, day = (int(part) for part in parts)
    if not 1 <= month <= 12:
        raise ValueError('month out of range: %d' % month)
    if not 1 <= day <= days_in_month(year, month):
        raise ValueError('day out of range: %d' % day)
    return year, month, day


def days_since_epoch(date_str):
    """Return the number of whole days from 1970-01-01 to `date_str`.

    Dates before the epoch yield negative counts.
    """
    year, month, day = parse_date(date_str)
    days_count = 0
    if year >= EPOCH_YEAR:
        for current in range(EPOCH_YEAR, year):
            days_count += days_in_year(current)
    else:
        for current in range(year, EPOCH_YEAR):
            days_count -= days_in_year(current)
    for current in range(1, month):
        days_count += days_in_month(year, current)
    return days_count + day - 1


def describe(date_str):
    """Build a one-line human readable summary for a single date."""
    days_count = days_since_epoch(date_str)
    label = 'day' if abs(days_count) == 1 else 'days'
    return '%s -> %d %s since the Unix epoch' % (date_str, days_count, label)


def main():
    """Report the epoch offset for a handful of representative dates."""
    for date_str in ('1970-01-01', '1970-01-02', '2000-02-29', '2024-12-31', '1969-12-31'):
        print(describe(date_str))


if __name__ == '__main__':
    main()

