"""Inventory stock checking utilities."""


def validate_inventory(inventory):
    """Return a cleaned copy of *inventory* with non-negative integer quantities.

    Raises TypeError if keys are not strings or values are not integers,
    and ValueError if a quantity is negative.
    """
    cleaned = {}
    for item, quantity in inventory.items():
        if not isinstance(item, str):
            raise TypeError("inventory keys must be strings, got %r" % (item,))
        if isinstance(quantity, bool) or not isinstance(quantity, int):
            raise TypeError("quantity for %r must be an int" % (item,))
        if quantity < 0:
            raise ValueError("quantity for %r must not be negative" % (item,))
        cleaned[item.strip().lower()] = quantity
    return cleaned


def normalise_items(items_to_check):
    """Return the requested item names, trimmed, lowercased and de-duplicated.

    The original order of first appearance is preserved so that reports
    read in the same order the caller asked for.
    """
    seen = []
    for item in items_to_check:
        if not isinstance(item, str):
            raise TypeError("items to check must be strings, got %r" % (item,))
        name = item.strip().lower()
        if name and name not in seen:
            seen.append(name)
    return seen


def check_stock(inventory, items_to_check):
    """Return a dict mapping each checked item to its available quantity.

    Items missing from *inventory* are reported with a quantity of 0.
    """
    stock = validate_inventory(inventory)
    stock_levels = {}
    for item in normalise_items(items_to_check):
        stock_levels[item] = stock.get(item, 0)
    return stock_levels


def split_by_availability(stock_levels):
    """Split stock levels into (in_stock, out_of_stock) name lists."""
    in_stock = [item for item, qty in stock_levels.items() if qty > 0]
    out_of_stock = [item for item, qty in stock_levels.items() if qty == 0]
    return in_stock, out_of_stock


def format_report(stock_levels):
    """Render *stock_levels* as an aligned, human readable text report."""
    if not stock_levels:
        return "No items requested."
    width = max(len(item) for item in stock_levels)
    lines = []
    for item, quantity in stock_levels.items():
        status = "available" if quantity else "OUT OF STOCK"
        lines.append("%-*s %5d  %s" % (width, item, quantity, status))
    in_stock, out_of_stock = split_by_availability(stock_levels)
    lines.append("%d available, %d out of stock" % (len(in_stock), len(out_of_stock)))
    return "\n".join(lines)


def main():
    """Check a sample warehouse against a shopping list and print the report."""
    warehouse = {'apple': 10, 'banana': 5, 'Milk': 0, 'bread': 3}
    wanted = ['apple', 'orange', 'milk', 'bread', 'apple']
    levels = check_stock(warehouse, wanted)
    print(levels)
    print(format_report(levels))
    print(check_stock({}, ['milk']))


if __name__ == "__main__":
    main()

