def validate_number(value, name):
    """Return value as an int, raising TypeError/ValueError if it is unusable."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError("%s must be an int, got %r" % (name, value))
    return value


def simulate_guess(target, guess):
    """Compare a guess against the target and return the round's feedback."""
    target = validate_number(target, "target")
    guess = validate_number(guess, "guess")
    if guess > target:
        return "Too high"
    if guess < target:
        return "Too low"
    return "Correct!"


def next_bounds(low, high, guess, feedback):
    """Narrow the search interval [low, high] using the feedback for guess."""
    if feedback == "Too high":
        return low, guess - 1
    if feedback == "Too low":
        return guess + 1, high
    return guess, guess


def play_game(target, low=1, high=100):
    """Play a full binary-search game and return the list of (guess, feedback) rounds."""
    if low > high:
        raise ValueError("empty range: low=%d high=%d" % (low, high))
    target = validate_number(target, "target")
    if not low <= target <= high:
        raise ValueError("target %d is outside [%d, %d]" % (target, low, high))
    rounds = []
    while True:
        guess = (low + high) // 2
        feedback = simulate_guess(target, guess)
        rounds.append((guess, feedback))
        if feedback == "Correct!":
            return rounds
        low, high = next_bounds(low, high, guess, feedback)


def format_round(index, guess, feedback):
    """Render one round as a single human-readable line."""
    return "Round %d: guessed %d -> %s" % (index, guess, feedback)


def report(target, rounds):
    """Build a multi-line report describing every round of a finished game."""
    lines = [format_round(i, guess, feedback)
             for i, (guess, feedback) in enumerate(rounds, start=1)]
    lines.append("Found %d in %d guess(es)." % (target, len(rounds)))
    return "\n".join(lines)


def main():
    """Demonstrate the single-round examples, then solve a couple of games."""
    examples = [(7, 5), (7, 7), (7, 9)]
    for target, guess in examples:
        print("simulate_guess(%d, %d) = %r" % (target, guess, simulate_guess(target, guess)))
    print()
    for target in (7, 42, 100):
        print(report(target, play_game(target)))
        print()


if __name__ == "__main__":
    main()

