def _validate_text(text):
    '''Return the input unchanged after confirming it is a string.

    Raises TypeError for anything that is not a str, since word counting
    only makes sense for textual input.
    '''
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    return text


def split_words(text):
    '''Split text into words on runs of spaces.

    Leading, trailing and repeated spaces produce no empty words.
    '''
    words = []
    current = []
    for char in text:
        if char == " ":
            if current:
                words.append("".join(current))
                current = []
        else:
            current.append(char)
    if current:
        words.append("".join(current))
    return words


def count_words(text):
    '''Count the words in text, where words are separated by spaces.

    >>> count_words('This is a test sentence.')
    5
    >>> count_words('  Hello   world  ')
    2
    '''
    word_count = len(split_words(_validate_text(text)))
    return word_count


def longest_word(text):
    '''Return the longest word in text.

    An empty string is returned when text holds no words at all.
    '''
    words = split_words(_validate_text(text))
    if not words:
        return ""
    return max(words, key=len)


def average_word_length(text):
    '''Return the mean length of the words in text as a float.

    Text without words averages to 0.0 rather than raising.
    '''
    words = split_words(_validate_text(text))
