def parse_point(text):
    """Parse a string like "1, 1" or "(-2, -3)" into a tuple of two floats.

    Raises ValueError if the text does not contain exactly two numbers.
    """
    cleaned = text.strip().strip("()[]")
    parts = [piece for piece in cleaned.replace(";", ",").split(",") if piece.strip()]
    if len(parts) != 2:
        raise ValueError("a point needs exactly two coordinates: %r" % text)
    return tuple(float(piece) for piece in parts)


def validate_point(p):
    """Return p as a tuple of two floats.

    Raises ValueError when p does not hold exactly two coordinates.
    """
    coords = tuple(p)
    if len(coords) != 2:
        raise ValueError("expected a 2D point, got %d coordinates" % len(coords))
    return tuple(float(value) for value in coords)


def manhattan_distance(p1, p2):
    """Return the Manhattan (taxicab) distance between two 2D points.

    >>> manhattan_distance((1, 1), (4, 5))
    7.0
    >>> manhattan_distance((0, 0), (-2, -3))
    5.0
    """
    x1, y1 = validate_point(p1)
    x2, y2 = validate_point(p2)
    return abs(x1 - x2) + abs(y1 - y2)


def distance_matrix(points):
    """Build the matrix of pairwise Manhattan distances.

    Row i holds the distances from points[i] to every point in the list.
    """
    return [[manhattan_distance(a, b) for b in points] for a in points]


def nearest_point(origin, candidates):
    """Return the candidate closest to origin under the Manhattan metric.

    Ties are broken by the order in which the candidates appear.
    """
    if not candidates:
        raise ValueError("no candidates to choose from")
    return min(candidates, key=lambda point: manhattan_distance(origin, point))


def format_point(p):
    """Render a point as a compact parenthesised pair of coordinates.

    Trailing zeros are dropped so that whole numbers stay short.
    """
    return "(%g, %g)" % validate_point(p)


def describe_pair(p1, p2):
    """Return a one-line report of the distance between two points.

    The two points are shown in formatted form on either side of an arrow.
    """
    return "%s -> %s : %.1f" % (format_point(p1), format_point(p2), manhattan_distance(p1, p2))


def main():
    """Report the metric for the sample pairs and for a small route.

    The route is read from text, then summarised by length and distance matrix.
    """
    for first, second in [((1, 1), (4, 5)), ((0, 0), (-2, -3))]:
        print(describe_pair(first, second))

    route = [parse_point(text) for text in ("(0, 0)", "3, -1", "(-2, 4)", "5; 5")]
    print("route points:", " ".join(format_point(point) for point in route))
    print("nearest to origin:", format_point(nearest_point((0.0, 0.0), route[1:])))

    total = sum(manhattan_distance(a, b) for a, b in zip(route, route[1:]))
    print("route length: %.1f" % total)

    for origin, row in zip(route, distance_matrix(route)):
        print(format_point(origin), " ".join("%5.1f" % value for value in row))


if __name__ == "__main__":
    main()

