"""Utilities for sorting lists of dictionaries by a shared key."""


def validate_records(dict_list, key):
    """Check that every entry is a dict containing ``key``.

    Raises TypeError for non-dict entries and KeyError when the key is absent.
    """
    if not isinstance(dict_list, list):
        raise TypeError("dict_list must be a list of dictionaries")
    for position, record in enumerate(dict_list):
        if not isinstance(record, dict):
            raise TypeError("entry at index %d is not a dict" % position)
        if key not in record:
            raise KeyError("entry at index %d has no key %r" % (position, key))


def sort_key_for(key):
    """Build a key function that reads ``key`` and makes values comparable.

    Numbers sort before strings so mixed columns do not raise TypeError.
    """
    def extract(record):
        value = record[key]
        if isinstance(value, bool):
            return (1, str(value))
        if isinstance(value, (int, float)):
            return (0, value)
        return (1, str(value))
    return extract


def sort_dicts_by_key(dict_list, key):
    """Return a new list with the dictionaries ordered by ``dict_list[i][key]``."""
    validate_records(dict_list, key)
    return sorted(dict_list, key=sort_key_for(key))


def column_names(dict_list):
    """Return the union of all keys, preserving first-seen order."""
    names = []
    for record in dict_list:
        for name in record:
            if name not in names:
                names.append(name)
    return names


def format_table(dict_list):
    """Render the records as an aligned text table with a header row."""
    names = column_names(dict_list)
    rows = [names]
    for record in dict_list:
        rows.append([str(record.get(name, "")) for name in names])
    widths = [max(len(row[i]) for row in rows) for i in range(len(names))]
    lines = []
    for row in rows:
        cells = [cell.ljust(widths[i]) for i, cell in enumerate(row)]
        lines.append(" | ".join(cells).rstrip())
    return "\n".join(lines)


def report(dict_list, key):
    """Sort the records by ``key`` and return a titled, formatted report."""
    ordered = sort_dicts_by_key(dict_list, key)
    return "sorted by %r:\n%s" % (key, format_table(ordered))


def main():
    """Sort a few sample data sets and print them as reports."""
    people = [{'name': 'B', 'age': 30}, {'name': 'A', 'age': 20}]
    ids = [{'id': 2}, {'id': 1}]
    print(report(people, 'age'))
    print()
    print(report(people, 'name'))
    print()
    print(report(ids, 'id'))


if __name__ == "__main__":
    main()

