def dimensions(matrix):
    """
    Return the (rows, columns) shape of a rectangular matrix.

    Raises ValueError if the rows do not all have the same length.
    """
    rows = len(matrix)
    if rows == 0:
        return (0, 0)
    cols = len(matrix[0])
    for row in matrix:
        if len(row) != cols:
            raise ValueError("matrix rows have inconsistent lengths")
    return (rows, cols)


def validate_operands(matrix1, matrix2):
    """
    Check that both operands are rectangular matrices of equal shape.

    Returns the common shape as a (rows, columns) tuple.
    """
    shape1 = dimensions(matrix1)
    shape2 = dimensions(matrix2)
    if shape1 != shape2:
        raise ValueError("shape mismatch: %r vs %r" % (shape1, shape2))
    return shape1


def subtract_rows(row1, row2):
    """
    Subtract two equally long rows element by element.
    """
    return [a - b for a, b in zip(row1, row2)]


def matrix_subtract(matrix1, matrix2):
    """
    Return the element-wise difference matrix1 - matrix2.
    """
    validate_operands(matrix1, matrix2)
    return [subtract_rows(row1, row2) for row1, row2 in zip(matrix1, matrix2)]


def format_number(value):
    """
    Render a number without a trailing ".0" for whole floats.
    """
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_matrix(matrix):
    """
    Render a matrix as aligned rows of right-justified numbers.
    """
    cells = [[format_number(value) for value in row] for row in matrix]
    width = max((len(text) for row in cells for text in row), default=1)
    return "\n".join(" ".join(text.rjust(width) for text in row) for row in cells)


def report_subtraction(matrix1, matrix2):
    """
    Build a human readable report of one subtraction.
    """
    result = matrix_subtract(matrix1, matrix2)
    rows, cols = dimensions(result)
    lines = ["%dx%d subtraction" % (rows, cols), format_matrix(matrix1),
             "minus", format_matrix(matrix2), "equals", format_matrix(result)]
    return "\n".join(lines)


def main():
    """
    Run the example subtractions and print their reports.
    """
    cases = [
        ([[1, 2], [3, 4]], [[1, 1], [1, 1]]),
        ([[5, 0]], [[1, -1]]),
        ([[2.5, -3], [10, 0.5]], [[0.5, 3], [4, 1.25]]),
    ]
    for matrix1, matrix2 in cases:
        print(report_subtraction(matrix1, matrix2))
        print()


if __name__ == "__main__":
    main()

