import random
from collections import Counter


def roll_die(sides=6):
    """Return the result of rolling a single fair die with the given number of sides."""
    return random.randint(1, sides)


def validate_num_dice(num_dice):
    """Check that num_dice is a non-negative integer and return it.

    Raises TypeError for non-integer input and ValueError for negative counts.
    """
    if isinstance(num_dice, bool) or not isinstance(num_dice, int):
        raise TypeError("num_dice must be an integer")
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")
    return num_dice


def roll_dice(num_dice):
    """Roll num_dice standard six-sided dice and return the individual results."""
    count = validate_num_dice(num_dice)
    return [roll_die() for _ in range(count)]


def simulate_dice_sum(num_dice):
    """Simulate rolling num_dice six-sided dice and return the total sum."""
    return sum(roll_dice(num_dice))


def sum_distribution(num_dice, trials):
    """Return a Counter mapping each observed total to how often it occurred."""
    if trials <= 0:
        raise ValueError("trials must be positive")
    return Counter(simulate_dice_sum(num_dice) for _ in range(trials))


def expected_sum(num_dice):
    """Return the theoretical mean total for num_dice six-sided dice."""
    return validate_num_dice(num_dice) * 3.5


def format_histogram(distribution, trials, width=40):
    """Render a distribution of totals as lines of text with proportional bars."""
    lines = []
    peak = max(distribution.values())
    for total in sorted(distribution):
        occurrences = distribution[total]
        bar = "#" * max(1, round(occurrences * width / peak))
        share = 100.0 * occurrences / trials
        lines.append(f"{total:>3} | {bar:<{width}} {share:5.1f}%")
    return "\n".join(lines)


def main():
    """Demonstrate single rolls and a sampled distribution for a few dice counts."""
    random.seed()
    for num_dice in (1, 2, 3):
        rolls = roll_dice(num_dice)
        print(f"{num_dice} die/dice -> {rolls} = {sum(rolls)}")

    trials = 6000
    for num_dice in (1, 2):
        distribution = sum_distribution(num_dice, trials)
        observed = sum(k * v for k, v in distribution.items()) / trials
        print(f"\nDistribution of simulate_dice_sum({num_dice}) over {trials} trials")
        print(format_histogram(distribution, trials))
        print(f"observed mean {observed:.3f}, expected {expected_sum(num_dice):.3f}")


if __name__ == "__main__":
    main()

