def parse_numbers(text):
    """Parse a whitespace or comma separated list of integers from ``text``.

    Returns the parsed list; raises ``ValueError`` when a token is not an
    integer, so callers can report bad input to the user.
    """
    tokens = text.replace(",", " ").split()
    return [int(token) for token in tokens]


def validate_input(numbers):
    """Check that ``numbers`` is a list of ints from 1..N with one repeat.

    ``N`` is ``len(numbers) - 1``, since exactly one value occurs twice.
    Returns ``N`` and raises ``ValueError`` when the list does not match
    that description.
    """
    if not isinstance(numbers, list):
        raise ValueError("numbers must be a list")
    if len(numbers) < 2:
        raise ValueError("numbers must contain at least two elements")
    limit = len(numbers) - 1
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("all elements must be integers")
        if value < 1 or value > limit:
            raise ValueError("elements must lie between 1 and %d" % limit)
    if len(set(numbers)) != limit:
        raise ValueError("exactly one value must be duplicated")
    return limit


