    """Return the single value that appears twice in ``numbers``.

    The list holds every integer from 1 to N once, except one value that
    appears twice, so the difference between the actual sum and the sum of
    1..N is precisely the duplicate.
    """
    limit = validate_input(numbers)
    expected = limit * (limit + 1) // 2
    return sum(numbers) - expected


