    The report names the duplicate and the two indices where it occurs.
    """
    duplicate = find_duplicate(numbers)
    positions = [index for index, value in enumerate(numbers) if value == duplicate]
    return "%s -> duplicate %d at indices %s" % (numbers, duplicate, positions)


