def validate_image(image_matrix):
    """Check that the argument is a rectangular matrix of [R, G, B] triples.

    Raises ValueError when the structure or the channel values are invalid.
    """
    if not isinstance(image_matrix, list):
        raise ValueError("image_matrix must be a list of rows")
    width = None
    for row in image_matrix:
        if not isinstance(row, list):
            raise ValueError("each row must be a list of pixels")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("all rows must have the same number of pixels")
        for pixel in row:
            validate_pixel(pixel)


def validate_pixel(pixel):
    """Ensure a single pixel is a triple of integers in the range 0..255."""
    if not isinstance(pixel, list) or len(pixel) != 3:
        raise ValueError("each pixel must be a list of three channels")
    for channel in pixel:
        if not isinstance(channel, int) or isinstance(channel, bool):
            raise ValueError("channel values must be integers")
        if channel < 0 or channel > 255:
            raise ValueError("channel values must lie between 0 and 255")


def pixel_average(pixel):
    """Return the integer average of the red, green and blue channels."""
    red, green, blue = pixel
    return (red + green + blue) // 3


def to_grayscale(image_matrix):
    """Convert an RGB image to grayscale by averaging each pixel's channels.

    The input is a 2D list of [R, G, B] triples; the result is a 2D list of
    integers of the same shape.
    """
    validate_image(image_matrix)
    return [[pixel_average(pixel) for pixel in row] for row in image_matrix]


def image_stats(grayscale_image):
    """Return the minimum, maximum and mean intensity of a grayscale image."""
    values = [value for row in grayscale_image for value in row]
    if not values:
        return 0, 0, 0.0
    return min(values), max(values), sum(values) / len(values)


RAMP = "@%#*+=-:. "


def render_ascii(grayscale_image):
    """Render a grayscale image as ASCII art, one string per image row."""
    lines = []
    for row in grayscale_image:
        lines.append("".join(RAMP[value * (len(RAMP) - 1) // 255] for value in row))
    return lines


def main():
    """Convert a few sample images and print their values, stats and art."""
    samples = [
        [[[255, 0, 0], [0, 255, 0]]],
        [[[10, 20, 30]]],
        [[[0, 0, 0], [128, 128, 128], [255, 255, 255]],
         [[255, 255, 0], [10, 90, 200], [60, 60, 60]]],
    ]
    for index, image in enumerate(samples, start=1):
        gray = to_grayscale(image)
        low, high, mean = image_stats(gray)
        print("Image {0}: {1}".format(index, gray))
        print("  min={0} max={1} mean={2:.2f}".format(low, high, mean))
        for line in render_ascii(gray):
            print("  |{0}|".format(line))


if __name__ == "__main__":
    main()

