def extract_numbers(text):
    """
    Return a string containing every digit of `text`, in original order.

    Non-digit characters are discarded; an empty result means the input held
    no digits at all.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a str, got {0}".format(type(text).__name__))
    return "".join(character for character in text if character.isdigit())


def split_numbers(text):
    """
    Split `text` into the maximal runs of consecutive digits.
    """
    runs = []
    current = ""
    for character in text:
        if character.isdigit():
            current += character
        elif current:
            runs.append(current)
            current = ""
    if current:
        runs.append(current)
    return runs


def sum_numbers(text):
    """
    Add up the integer values of the digit runs found in `text`.
    """
    return sum(int(run) for run in split_numbers(text))


def digit_histogram(text):
    """
    Map each digit present in `text` to the number of times it occurs.
    """
    histogram = {}
    for digit in extract_numbers(text):
        histogram[digit] = histogram.get(digit, 0) + 1
    return histogram


def format_histogram(histogram):
    """
    Render a digit histogram as a compact, digit-ordered line of text.
    """
    if not histogram:
        return "(no digits)"
    parts = ["{0} x{1}".format(digit, histogram[digit]) for digit in sorted(histogram)]
    return ", ".join(parts)


def describe(text):
    """
    Build a multi-line report about the digits contained in `text`.
    """
    runs = split_numbers(text)
    return "\n".join([
        "input    : {0!r}".format(text),
        "digits   : {0!r}".format(extract_numbers(text)),
        "runs     : {0}".format(" ".join(runs) if runs else "(none)"),
        "total    : {0}".format(sum_numbers(text)),
        "histogram: {0}".format(format_histogram(digit_histogram(text))),
    ])


def main():
    """
    Report on a few sample strings.
    """
    samples = [
        "abc123def45",
        "No numbers here.",
        "Order 66 shipped on 2024-03-07 for $19.99",
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

