def count_frequencies(numbers):
    """Build a mapping from each value in ``numbers`` to how often it occurs.

    The keys keep the original numeric type, so integers and floats that
    compare equal (such as ``2`` and ``2.0``) are grouped together.
    """
    counts = {}
    for value in numbers:
        counts[value] = counts.get(value, 0) + 1
    return counts


def validate_numbers(numbers):
    """Return ``numbers`` as a list, raising if it cannot hold a mode.

    An empty sequence has no most frequent element, and non-numeric items
    cannot be compared or reported, so both cases are rejected early.
    """
    values = list(numbers)
    if not values:
        raise ValueError("cannot compute the mode of an empty sequence")
    for value in values:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("all items must be int or float, got %r" % (value,))
    return values


def calculate_mode(numbers):
    """Return the most frequent number in ``numbers``.

    When several values share the highest frequency, the one that appears
    first in the input is returned.
    """
    values = validate_numbers(numbers)
    counts = count_frequencies(values)
    return max(counts, key=lambda value: (counts[value], -values.index(value)))


def all_modes(numbers):
    """Return every value tied for the highest frequency.

    The modes are listed in the order in which they first appear in the
    input, so the result is stable for equally frequent values.
    """
    values = validate_numbers(numbers)
    counts = count_frequencies(values)
    best = max(counts.values())
    seen = []
    for value in values:
        if counts[value] == best and value not in seen:
            seen.append(value)
    return seen


def format_number(value):
    """Render ``value`` as text for the report.

    Whole floats lose their trailing ``.0`` so that ``7.0`` and ``7`` look
    the same in the output.
    """
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe_mode(numbers):
    """Build a one-line human readable report about the mode of ``numbers``.

    Ties mention every mode and state which one ``calculate_mode`` returns.
    """
    modes = all_modes(numbers)
    counts = count_frequencies(numbers)
    chosen = calculate_mode(numbers)
    occurrences = counts[chosen]
    rendered = ", ".join(format_number(value) for value in modes)
    if len(modes) > 1:
        return "modes %s (%d occurrences each); returning %s" % (
            rendered, occurrences, format_number(chosen))
    return "mode %s (%d occurrences)" % (rendered, occurrences)


def main():
    """Print a mode report for a few sample datasets.
    """
    datasets = [
        [1, 2, 2, 3, 3, 3, 4],
        [5, 5, 1, 1],
        [2.5, 2.5, 7.0],
        [42],
    ]
    for dataset in datasets:
        rendered = ", ".join(format_number(value) for value in dataset)
        print("[%s] -> %s" % (rendered, describe_mode(dataset)))


if __name__ == "__main__":
    main()

