def get_item_quantity(inventory, item_name):
    """
    Return the quantity of ``item_name`` in ``inventory``, or 0 if absent.

    The lookup is tolerant of surrounding whitespace and letter case, so
    ``'Apple '`` finds the same entry as ``'apple'``.
    """
    key = normalize_name(item_name)
    for name, quantity in inventory.items():
        if normalize_name(name) == key:
            return int(quantity)
    return 0


def normalize_name(item_name):
    """
    Return a canonical form of an item name for comparison purposes.
    """
    return str(item_name).strip().lower()


def is_in_stock(inventory, item_name):
    """
    Tell whether at least one unit of ``item_name`` is available.
    """
    return get_item_quantity(inventory, item_name) > 0


def total_units(inventory):
    """
    Return the sum of all quantities stored in ``inventory``.
    """
    return sum(int(quantity) for quantity in inventory.values())


def items_below(inventory, threshold):
    """
    List item names whose quantity is strictly under ``threshold``.

    The result is sorted alphabetically so reports are stable between runs.
    """
    low = [name for name in inventory if get_item_quantity(inventory, name) < threshold]
    return sorted(low, key=normalize_name)


def restock_amount(inventory, item_name, target):
    """
    Return how many units must be added to reach ``target`` for an item.
    """
    missing = target - get_item_quantity(inventory, item_name)
    return max(missing, 0)


def format_lookup(inventory, item_name):
    """
    Build a one-line human readable answer for a single item lookup.
    """
    quantity = get_item_quantity(inventory, item_name)
    if quantity == 0:
        return "{0}: out of stock".format(item_name)
    return "{0}: {1} unit(s)".format(item_name, quantity)


def stock_report(inventory, queries, threshold=6, target=12):
    """
    Assemble a multi-line report answering ``queries`` against the stock.
    """
    lines = [format_lookup(inventory, name) for name in queries]
    lines.append("total units in stock: {0}".format(total_units(inventory)))
    for name in items_below(inventory, threshold):
        lines.append(
            "restock {0}: order {1}".format(name, restock_amount(inventory, name, target))
        )
    return "\n".join(lines)


def main():
    """
    Run a small stock enquiry session over a sample inventory.
    """
    inventory = {'apple': 10, 'banana': 5, 'cherry': 0, 'date': 21}
    queries = ['apple', 'orange', 'Banana ', 'cherry']
    print(stock_report(inventory, queries))
    for name in queries:
        availability = "yes" if is_in_stock(inventory, name) else "no"
        print("available {0}? {1}".format(normalize_name(name), availability))


if __name__ == '__main__':
    main()

