from collections import Counter


def normalize(text):
    """Return only the letters of *text*, lowercased, ignoring spaces and punctuation."""
    if not isinstance(text, str):
        raise TypeError("expected a string, got %r" % type(text).__name__)
    return "".join(ch.lower() for ch in text if ch.isalpha())


def letter_counts(text):
    """Return a Counter mapping each letter of the normalized *text* to its frequency."""
    return Counter(normalize(text))


def are_anagrams(str1, str2):
    """Return True if *str1* and *str2* use the same letters, ignoring case and spaces."""
    return letter_counts(str1) == letter_counts(str2)


def letter_difference(str1, str2):
    """Return the letters of *str1* that are left over once *str2* has been matched."""
    return letter_counts(str1) - letter_counts(str2)


def describe_pair(str1, str2):
    """Build a human readable sentence explaining the verdict for one pair of strings."""
    if are_anagrams(str1, str2):
        return "%r and %r are anagrams." % (str1, str2)
    extra_left = letter_difference(str1, str2)
    extra_right = letter_difference(str2, str1)
    details = []
    if extra_left:
        details.append("only in first: " + format_counts(extra_left))
    if extra_right:
        details.append("only in second: " + format_counts(extra_right))
    return "%r and %r are not anagrams (%s)." % (str1, str2, "; ".join(details))


def format_counts(counts):
    """Render a Counter of letters as a compact, alphabetically sorted string."""
    parts = []
    for letter in sorted(counts):
        amount = counts[letter]
        parts.append(letter if amount == 1 else "%s*%d" % (letter, amount))
    return ",".join(parts)


def group_anagrams(words):
    """Group *words* into lists that share the same normalized letter signature."""
    groups = {}
    for word in words:
        signature = "".join(sorted(normalize(word)))
        groups.setdefault(signature, []).append(word)
    return [group for _, group in sorted(groups.items()) if len(group) > 1]


def main():
    """Check a few sample pairs and report the anagram families found in a word list."""
    pairs = [
        ("listen", "silent"),
        ("hello", "world"),
        ("Dormitory", "Dirty Room"),
        ("Conversation", "Voices rant on"),
    ]
    for first, second in pairs:
        print(describe_pair(first, second))

    words = ["evil", "vile", "live", "stone", "tones", "notes", "python"]
    print("\nAnagram families:")
    for family in group_anagrams(words):
        print("  " + " = ".join(family))


if __name__ == "__main__":
    main()

