def _ensure_list(name, value):
    """Return ``value`` unchanged after checking that it is a list.

    Raises TypeError with the argument name so callers get a clear message
    when they pass, for example, a string or a generator.
    """
    if not isinstance(value, list):
        raise TypeError("%s must be a list, got %s" % (name, type(value).__name__))
    return value


def _split_by_hashability(items):
    """Split ``items`` into a set of hashable values and a list of the rest.

    Membership tests against the set are constant time, while unhashable
    values such as lists or dicts have to be compared one by one.
    """
    hashable = set()
    unhashable = []
    for item in items:
        try:
            hashable.add(item)
        except TypeError:
            unhashable.append(item)
    return hashable, unhashable


def find_common_elements(list1, list2):
    """Return the elements that appear in both ``list1`` and ``list2``.

    Each common element appears once in the result and the order of the
    result follows the first occurrence in ``list1``.
    """
    _ensure_list("list1", list1)
    _ensure_list("list2", list2)
    hashable, unhashable = _split_by_hashability(list2)
    common = []
    for item in list1:
        try:
            present = item in hashable
        except TypeError:
            present = any(item == other for other in unhashable)
        if present and not any(item == seen for seen in common):
            common.append(item)
    return common


def describe_overlap(list1, list2):
    """Build a one-line summary of the overlap between two lists.

    The summary names both inputs and lists the shared elements, or says
    plainly that there are none.
    """
    common = find_common_elements(list1, list2)
    if not common:
        return "%r and %r share no elements" % (list1, list2)
    return "%r and %r share %d element(s): %r" % (list1, list2, len(common), common)


def main():
    """Print an overlap summary for a few representative list pairs.

    The pairs cover plain numbers, disjoint strings, duplicated values and
    unhashable members, and the final call shows the input validation.
    """
    pairs = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        ([1, 1, 2, 2, 3], [2, 3, 3, 9]),
        ([[1, 2], {'k': 1}, 'x'], ['x', [1, 2]]),
    ]
    for first, second in pairs:
        print(describe_overlap(first, second))
    try:
        find_common_elements([1, 2], (3, 4))
    except TypeError as exc:
        print("rejected bad input:", exc)


if __name__ == "__main__":
    main()

