def normalize(card_number):
    """Strip spaces and dashes commonly used to group card digits."""
    return card_number.replace(" ", "").replace("-", "")


def is_digit_string(text):
    """Return True when text is non-empty and contains only decimal digits."""
    return bool(text) and all(character in "0123456789" for character in text)


def to_digits(card_number):
    """Convert a cleaned card number into a list of integer digits."""
    cleaned = normalize(card_number)
    if not is_digit_string(cleaned):
        raise ValueError("card number must contain digits only: %r" % card_number)
    return [int(character) for character in cleaned]


def double_and_reduce(digit):
    """Double a digit and subtract 9 when the result exceeds a single digit."""
    doubled = digit * 2
    if doubled > 9:
        doubled -= 9
    return doubled


def luhn_sum(card_number):
    """Compute the Luhn checksum: every second digit from the right is doubled."""
    digits = to_digits(card_number)
    total = 0
    for position, digit in enumerate(reversed(digits)):
        if position % 2 == 1:
            total += double_and_reduce(digit)
        else:
            total += digit
    return total


def is_valid_luhn(card_number):
    """Return True when the card number's Luhn checksum is a multiple of ten."""
    return luhn_sum(card_number) % 10 == 0


def check_digit_for(payload):
    """Return the digit that would make payload a valid Luhn number."""
    return (10 - luhn_sum(payload + "0") % 10) % 10


def mask(card_number):
    """Hide all but the last four digits of a card number for safe display."""
    cleaned = normalize(card_number)
    if len(cleaned) <= 4:
        return cleaned
    return "*" * (len(cleaned) - 4) + cleaned[-4:]


def describe(card_number):
    """Build a one-line report about a single card number."""
    try:
        verdict = "VALID" if is_valid_luhn(card_number) else "INVALID"
    except ValueError as error:
        return "%-20s rejected (%s)" % (card_number, error)
    return "%-20s sum=%-4d %-7s expected check digit %d" % (
        mask(card_number),
        luhn_sum(card_number),
        verdict,
        check_digit_for(normalize(card_number)[:-1]),
    )


def main():
    """Report on a handful of sample card numbers."""
    samples = [
        "49927398716",
        "49927398717",
        "1234567890123456",
        "4539 1488 0343 6467",
        "4539-1488-0343-6468",
        "1234abcd",
    ]
    for sample in samples:
        print(describe(sample))


if __name__ == "__main__":
    main()

