import math


def euclidean_distance_2d(x1: float, y1: float, x2: float, y2: float) -> float:
    """Return the Euclidean distance between (x1, y1) and (x2, y2)."""
    dx = float(x2) - float(x1)
    dy = float(y2) - float(y1)
    return math.hypot(dx, dy)


def parse_point(text: str) -> tuple:
    """Parse a point written as "x,y" (or "x y") into a pair of floats.

    Raises ValueError if the text does not contain exactly two numbers.
    """
    parts = text.replace(",", " ").split()
    if len(parts) != 2:
        raise ValueError("a point needs exactly two coordinates: %r" % text)
    return float(parts[0]), float(parts[1])


def distance_between(point_a: tuple, point_b: tuple) -> float:
    """Return the distance between two (x, y) tuples."""
    return euclidean_distance_2d(point_a[0], point_a[1], point_b[0], point_b[1])


def path_length(points: list) -> float:
    """Return the total length of the polyline through the given points."""
    total = 0.0
    for start, end in zip(points, points[1:]):
        total += distance_between(start, end)
    return total


def closest_pair(points: list) -> tuple:
    """Return (index_a, index_b, distance) for the closest pair of points.

    Requires at least two points.
    """
    if len(points) < 2:
        raise ValueError("closest_pair needs at least two points")
    best = None
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            d = distance_between(points[i], points[j])
            if best is None or d < best[2]:
                best = (i, j, d)
    return best


def format_point(point: tuple) -> str:
    """Format an (x, y) tuple for display, trimming trailing zeros."""
    return "({0:g}, {1:g})".format(point[0], point[1])


def report(raw_points: list) -> str:
    """Build a human readable report about a list of textual points."""
    points = [parse_point(text) for text in raw_points]
    lines = ["Points: " + " -> ".join(format_point(p) for p in points)]
    for start, end in zip(points, points[1:]):
        lines.append(
            "  {0} to {1}: {2:.4f}".format(
                format_point(start), format_point(end), distance_between(start, end)
            )
        )
    lines.append("Path length: {0:.4f}".format(path_length(points)))
    i, j, d = closest_pair(points)
    lines.append(
        "Closest pair: {0} and {1} at {2:.4f}".format(
            format_point(points[i]), format_point(points[j]), d
        )
    )
    return "\n".join(lines)


def main() -> None:
    """Demonstrate the distance helpers on a small set of points."""
    print(euclidean_distance_2d(0, 0, 3, 4))
    print(euclidean_distance_2d(1, 1, 1, 1))
    print(report(["0,0", "3,4", "3.5 1", "-2,-1"]))


if __name__ == "__main__":
    main()

