def validate_inputs(input_dict, threshold):
    """Check that the arguments are a dictionary and a numeric threshold.

    Raises TypeError if the types are not usable for comparison.
    """
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict, got %s" % type(input_dict).__name__)
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be an int or float")
    return True


def filter_dict_by_value(input_dict, threshold):
    """Return a new dict with only the pairs whose value exceeds threshold.

    Non-numeric values are skipped, since they cannot be compared to a number.
    """
    validate_inputs(input_dict, threshold)
    result = {}
    for key, value in input_dict.items():
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            continue
        if value > threshold:
            result[key] = value
    return result


def sort_by_value(filtered):
    """Order the surviving items by descending value.

    Keys are compared as strings to break ties deterministically.
    """
    return sorted(filtered.items(), key=lambda pair: (-pair[1], str(pair[0])))


def summarize(filtered):
    """Return count, total and maximum value of the filtered mapping.

    The total and maximum are None when nothing survived the filter.
    """
    values = list(filtered.values())
    if not values:
        return {"count": 0, "total": None, "maximum": None}
    return {"count": len(values), "total": sum(values), "maximum": max(values)}


