ABSOLUTE_ZERO_C = -273.15


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit using F = C * 9/5 + 32."""
    return float(celsius) * 9.0 / 5.0 + 32.0


def fahrenheit_to_celsius(fahrenheit):
    """Convert a Fahrenheit temperature back to Celsius."""
    return (float(fahrenheit) - 32.0) * 5.0 / 9.0


def parse_temperature(text):
    """Parse a user-supplied Celsius value, accepting a trailing 'C' unit."""
    cleaned = text.strip().rstrip("cC").strip()
    try:
        return float(cleaned)
    except ValueError:
        raise ValueError("not a valid temperature: %r" % text)


def validate_celsius(celsius):
    """Return the value unchanged, or raise if it lies below absolute zero."""
    if celsius < ABSOLUTE_ZERO_C:
        raise ValueError("%.2f C is below absolute zero" % celsius)
    return celsius


def format_row(celsius):
    """Render one Celsius/Fahrenheit pair as an aligned table row."""
    return "%10.2f %12.2f" % (celsius, celsius_to_fahrenheit(celsius))


def build_table(values):
    """Build a header plus one formatted row per validated Celsius value."""
    lines = ["%10s %12s" % ("Celsius", "Fahrenheit"), "-" * 23]
    for value in values:
        lines.append(format_row(validate_celsius(value)))
    return lines


def convert_all(texts):
    """Parse each text entry and return the matching Fahrenheit values."""
    results = []
    for text in texts:
        celsius = validate_celsius(parse_temperature(text))
        results.append(celsius_to_fahrenheit(celsius))
    return results


def scale_summary(celsius):
    """Describe a temperature relative to the freezing and boiling points."""
    if celsius <= 0.0:
        label = "at or below freezing"
    elif celsius >= 100.0:
        label = "at or above boiling"
    else:
        label = "liquid water range"
    return "%.1f C (%.1f F) is %s" % (celsius, celsius_to_fahrenheit(celsius), label)


def main():
    """Print a conversion table and a few summaries for sample inputs."""
    for line in build_table([-40.0, 0.0, 37.0, 100.0]):
        print(line)

    print()
    for fahrenheit in convert_all(["0", "100 C", "21.5c"]):
        print("%.2f F is %.2f C" % (fahrenheit, fahrenheit_to_celsius(fahrenheit)))

    print()
    for celsius in (-12.0, 25.0, 150.0):
        print(scale_summary(celsius))

    try:
        celsius_to_fahrenheit(validate_celsius(-300.0))
    except ValueError as error:
        print("rejected: %s" % error)


if __name__ == "__main__":
    main()

