def strip_query_prefix(text):
    """Return the query portion of text, dropping any leading URL or question mark."""
    if '?' in text:
        return text.split('?', 1)[1]
    return text


def is_hex_pair(digits):
    """Report whether digits is exactly two hexadecimal characters."""
    return len(digits) == 2 and all(d in '0123456789abcdefABCDEF' for d in digits)


def decode_percent_escapes(text):
    """Decode percent-escape sequences in text, leaving other characters alone."""
    out = []
    index = 0
    while index < len(text):
        char = text[index]
        if char == '%' and is_hex_pair(text[index + 1:index + 3]):
            out.append(chr(int(text[index + 1:index + 3], 16)))
            index += 3
            continue
        out.append(char)
        index += 1
    return ''.join(out)


def split_pairs(query_string):
    """Split a query string on ampersands, discarding empty segments."""
    return [chunk for chunk in query_string.split('&') if chunk]


def parse_pair(pair):
    """Turn one key=value segment into a decoded key and value tuple."""
    if '=' in pair:
        key, value = pair.split('=', 1)
    else:
        key, value = pair, ''
    return decode_percent_escapes(key), decode_percent_escapes(value)


def parse_url_params(query_string):
    """Parse query_string into a dictionary mapping parameter names to values."""
    if not isinstance(query_string, str):
        raise TypeError('query_string must be a str')
    params = {}
    for pair in split_pairs(strip_query_prefix(query_string)):
        key, value = parse_pair(pair)
        if key:
            params[key] = value
    return params


def format_params(params):
    """Render a parsed parameter mapping as aligned key and value lines."""
    if not params:
        return '(no parameters)'
    width = max(len(key) for key in params)
    lines = ['{0:<{1}} : {2}'.format(key, width, value) for key, value in params.items()]
    return '\n'.join(lines)


def main():
    """Parse a few sample query strings and print the resulting mappings."""
    samples = [
        'name=John&age=30',
        'q=python+programming',
        'https://example.com/search?q=caf%C3%A9&page=2&debug',
    ]
    for sample in samples:
        print(sample)
        print(format_params(parse_url_params(sample)))
        print()


if __name__ == '__main__':
    main()

