def _validate(strings):
    """Check that ``strings`` is a list of ``str`` and return it unchanged.

    Raises TypeError if the container or any element has the wrong type.
    """
    if not isinstance(strings, list):
        raise TypeError("strings must be a list of str")
    for item in strings:
        if not isinstance(item, str):
            raise TypeError("every element of strings must be a str")
    return strings


def common_prefix_of_pair(left, right):
    """Return the longest string that begins both ``left`` and ``right``."""
    limit = min(len(left), len(right))
    index = 0
    while index < limit and left[index] == right[index]:
        index += 1
    return left[:index]


def longest_common_prefix(strings):
    """Return the longest prefix shared by all strings in ``strings``.

    An empty list or a list whose members share no leading character
    yields the empty string.
    """
    _validate(strings)
    if not strings:
        return ""
    prefix = strings[0]
    for candidate in strings[1:]:
        prefix = common_prefix_of_pair(prefix, candidate)
        if not prefix:
            break
    return prefix


def group_by_prefix(strings, length):
    """Group ``strings`` by their first ``length`` characters.

    Returns a dict mapping each prefix to the list of words that start
    with it, preserving the order in which the words were seen.
    """
    groups = {}
    for word in _validate(strings):
        groups.setdefault(word[:length], []).append(word)
    return groups


def describe(strings):
    """Build a human readable one-line summary of the common prefix."""
    prefix = longest_common_prefix(strings)
    words = ", ".join(repr(word) for word in strings)
    if not prefix:
        return "[{}] share no common prefix".format(words)
    return "[{}] share the prefix {!r} ({} chars)".format(words, prefix, len(prefix))


def main():
    """Run the reporting pipeline over a few sample word lists."""
    samples = [
        ["flower", "flow", "flight"],
        ["dog", "racecar", "car"],
        ["interspecies", "interstellar", "interstate"],
        ["alone"],
        [],
    ]
    for sample in samples:
        print(describe(sample))
    mixed = ["throne", "throw", "thrust", "trap", "trial"]
    print("Grouping {!r} by 3-character prefixes:".format(mixed))
    for prefix, words in group_by_prefix(mixed, 3).items():
        print("  {}: {}".format(prefix, " ".join(words)))


if __name__ == "__main__":
    main()

