def read_text(filepath):
    """Return the entire contents of ``filepath`` as a single string."""
    with open(filepath, "r", encoding="utf-8") as handle:
        return handle.read()


def split_words(text):
    """Split ``text`` into words on any run of whitespace, dropping empties."""
    return text.split()


def count_words_in_text(text):
    """Return the number of whitespace-separated words contained in ``text``."""
