def has_all_unique_chars(s):
    """
    Return True when every character in *s* occurs exactly once.

    An empty string trivially satisfies the condition. Comparison is
    case-sensitive, so 'aA' is considered unique.
    """
    if not isinstance(s, str):
        raise TypeError("expected a string, got %s" % type(s).__name__)
    seen = set()
    for char in s:
        if char in seen:
            return False
        seen.add(char)
    return True


def first_repeated_char(s):
    """
    Return the first character that repeats in *s*, or None if there is none.
    """
    seen = set()
    for char in s:
        if char in seen:
            return char
        seen.add(char)
    return None


def duplicate_counts(s):
    """
    Map each repeated character of *s* to the number of times it appears.
    """
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1
    return {char: n for char, n in counts.items() if n > 1}


def describe(s):
    """
    Build a human-readable one-line verdict about the uniqueness of *s*.
    """
    if has_all_unique_chars(s):
        return "%r: all characters are unique" % s
    culprit = first_repeated_char(s)
    extras = duplicate_counts(s)
    detail = ", ".join(
        "%r x%d" % (char, n) for char, n in sorted(extras.items())
    )
    return "%r: not unique (first repeat %r; duplicates: %s)" % (s, culprit, detail)


def normalize(s, ignore_case=False, ignore_spaces=False):
    """
    Return a copy of *s* prepared according to the requested relaxations.

    Lowercasing lets 'Aa' count as a repeat, and dropping whitespace lets
    phrases with several words be judged on their letters only.
    """
    result = s
    if ignore_case:
        result = result.lower()
    if ignore_spaces:
        result = "".join(result.split())
    return result


def report(samples, ignore_case=False, ignore_spaces=False):
    """
    Yield a verdict line for each sample after normalizing it.
    """
    for sample in samples:
        yield describe(normalize(sample, ignore_case, ignore_spaces))


def main():
    """
    Run the uniqueness check over a handful of representative strings.
    """
    for line in report(["abcde", "hello", "", "aA", "1234567890"]):
        print(line)
    print("--- ignoring case and spaces ---")
    loose_samples = ["Dermatoglyphics", "the quick brown fox", "Aa"]
    for line in report(loose_samples, ignore_case=True, ignore_spaces=True):
        print(line)


if __name__ == "__main__":
    main()

