"""Utilities for reversing strings and reporting on the results."""


def reverse_string(input_string):
    """Return a new string with the characters of `input_string` reversed.

    Raises TypeError if `input_string` is not a str.
    """
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a str, got %s" % type(input_string).__name__)
    return input_string[::-1]


def reverse_words(input_string):
    """Reverse the order of whitespace-separated words, keeping each word intact."""
    words = input_string.split()
    words.reverse()
    return " ".join(words)


def is_palindrome(input_string):
    """Report whether `input_string` reads the same forwards and backwards.

    Case and non-alphanumeric characters are ignored, so "A man, a plan"
    style inputs are judged on their letters and digits alone.
    """
    cleaned = "".join(ch.lower() for ch in input_string if ch.isalnum())
    return cleaned == reverse_string(cleaned)


def describe(input_string):
    """Build a dictionary summarising the reversal of a single string."""
    return {
        "original": input_string,
        "reversed": reverse_string(input_string),
        "words_reversed": reverse_words(input_string),
        "palindrome": is_palindrome(input_string),
    }


def format_report(summary):
    """Render a summary produced by `describe` as a single printable line."""
    tag = "palindrome" if summary["palindrome"] else "not a palindrome"
    return "{original!r} -> {reversed!r} | words: {words!r} | {tag}".format(
        original=summary["original"],
        reversed=summary["reversed"],
        words=summary["words_reversed"],
        tag=tag,
    )


def main():
    """Reverse a few sample strings and print a report for each one."""
    samples = [
        "hello",
        "Python",
        "never odd or even",
        "the quick brown fox",
        "",
    ]
    for sample in samples:
        print(format_report(describe(sample)))

    try:
        reverse_string(12345)
    except TypeError as error:
        print("rejected bad input:", error)


if __name__ == "__main__":
    main()

