def validate(numbers):
    """Check that `numbers` is a list of at least four positive integers.

    Raises ValueError if the input does not satisfy the task's contract.
    """
    if not isinstance(numbers, list):
        raise ValueError("numbers must be a list")
    if len(numbers) < 4:
        raise ValueError("numbers must contain at least four values")
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("all values must be integers: %r" % (value,))
        if value <= 0:
            raise ValueError("all values must be positive: %d" % value)


def two_smallest(numbers):
    """Return the two smallest values of `numbers` as a tuple (lowest first).

    A single pass keeps the running minimum and runner-up, so the function
    works for very large inputs without sorting the whole list.
    """
    first = second = None
    for value in numbers:
        if first is None or value < first:
            first, second = value, first
        elif second is None or value < second:
            second = value
    return first, second


def sum_two_smallest(numbers):
    """Return the sum of the two smallest positive numbers in `numbers`."""
    validate(numbers)
    low, runner_up = two_smallest(numbers)
    return low + runner_up


def parse_numbers(text):
    """Parse a whitespace- or comma-separated string into a list of integers."""
    tokens = text.replace(",", " ").split()
    result = []
    for token in tokens:
        try:
            result.append(int(token))
        except ValueError:
            raise ValueError("not an integer: %r" % token)
    return result


def describe(numbers):
    """Build a one-line report of the two smallest numbers and their sum."""
    low, runner_up = two_smallest(numbers)
    total = sum_two_smallest(numbers)
    return "%d + %d = %d" % (low, runner_up, total)


def main(argv):
    """Read numbers from the command line (or use built-in samples) and report.

    Returns a process exit status: 0 on success, 1 if the input is invalid.
    """
    if len(argv) > 1:
        datasets = [parse_numbers(" ".join(argv[1:]))]
    else:
        datasets = [
            [19, 5, 42, 2, 77],
            [10, 343445353, 3453445, 3453545353453],
        ]
    status = 0
    for numbers in datasets:
        try:
            print(describe(numbers))
        except ValueError as error:
            print("error: %s" % error)
            status = 1
    return status


if __name__ == "__main__":
    import sys

    sys.exit(main(sys.argv))

