def validate_event(event):
    """Check that an event is a pair of integers with start before end.

    Raises ValueError if the tuple is malformed, TypeError if the times are
    not integers. Returns the event as a plain (start, end) tuple.
    """
    if not isinstance(event, (tuple, list)) or len(event) != 2:
        raise ValueError("an event must be a (start_time, end_time) pair: %r" % (event,))
    start, end = event
    if isinstance(start, bool) or isinstance(end, bool) or not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("event times must be integers: %r" % (event,))
    if start > end:
        raise ValueError("event start must not follow its end: %r" % (event,))
    return (start, end)


def check_event_overlap(event1, event2):
    """Return True if the two events share at least one minute of time.

    Events that merely touch (one ends exactly when the other starts) are not
    considered overlapping.
    """
    start1, end1 = validate_event(event1)
    start2, end2 = validate_event(event2)
    return start1 < end2 and start2 < end1


def overlap_duration(event1, event2):
    """Return the number of minutes shared by the two events (0 if disjoint)."""
    start1, end1 = validate_event(event1)
    start2, end2 = validate_event(event2)
    return max(0, min(end1, end2) - max(start1, start2))


def format_time(minutes):
    """Render minutes-from-midnight as a 24-hour HH:MM string."""
    hours, mins = divmod(minutes, 60)
    return "%02d:%02d" % (hours % 24, mins)


def format_event(event):
    """Render an event as a readable 'HH:MM-HH:MM' range."""
    start, end = validate_event(event)
    return "%s-%s" % (format_time(start), format_time(end))


def find_conflicts(events):
    """Return every pair of indices whose events overlap.

    The result is a list of (index1, index2, shared_minutes) triples ordered by
    the position of the events in the input sequence.
    """
    conflicts = []
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if check_event_overlap(events[i], events[j]):
                conflicts.append((i, j, overlap_duration(events[i], events[j])))
    return conflicts


def conflict_report(events):
    """Build a multi-line human-readable summary of a schedule's conflicts."""
    lines = ["Schedule of %d event(s):" % len(events)]
    for index, event in enumerate(events):
        lines.append("  [%d] %s" % (index, format_event(event)))
    conflicts = find_conflicts(events)
    if not conflicts:
        lines.append("No conflicts found.")
    for i, j, shared in conflicts:
        lines.append("  Conflict: [%d] %s overlaps [%d] %s by %d minute(s)"
                     % (i, format_event(events[i]), j, format_event(events[j]), shared))
    return "\n".join(lines)


def main():
    """Run the documented examples and report on a small sample schedule."""
    print(check_event_overlap((10, 20), (15, 25)))
    print(check_event_overlap((10, 15), (20, 25)))
    schedule = [(540, 600), (570, 630), (660, 720), (700, 760), (1380, 1440)]
    print(conflict_report(schedule))


if __name__ == "__main__":
    main()

