def mean(numbers):
    """Return the arithmetic mean of *numbers*, or 0.0 for an empty sequence."""
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)


def mean_absolute_deviation(numbers):
    """Return the mean absolute deviation of *numbers* around their mean.

    The mean absolute deviation is the average of |x - mean| over all
    elements.  An empty list has no centre, so 0.0 is returned.
    """
    if not numbers:
        return 0.0
    centre = mean(numbers)
    return sum(abs(value - centre) for value in numbers) / len(numbers)


def parse_numbers(text):
    """Parse a whitespace- or comma-separated string into a list of floats.

    Raises ValueError with the offending token when a field is not numeric.
    """
    fields = [field for field in text.replace(",", " ").split() if field]
    values = []
    for field in fields:
        try:
            values.append(float(field))
        except ValueError:
            raise ValueError("not a number: {!r}".format(field))
    return values


def median(numbers):
    """Return the median of *numbers*, or 0.0 for an empty sequence."""
    if not numbers:
        return 0.0
    ordered = sorted(numbers)
