class ToDoList:
    """A simple to-do list tracking task names and their completion state."""

    def __init__(self):
        """Create an empty to-do list."""
        self._tasks = {}
        self._order = []

    def add_task(self, task_name):
        """Add a task by name, ignoring a name that is already present."""
        name = _normalize(task_name)
        if name not in self._tasks:
            self._tasks[name] = False
            self._order.append(name)

    def mark_completed(self, task_name):
        """Mark an existing task as completed; raise KeyError if unknown."""
        name = _normalize(task_name)
        if name not in self._tasks:
            raise KeyError("no such task: {!r}".format(task_name))
        self._tasks[name] = True

    def get_pending_tasks(self):
        """Return the names of tasks that are not yet completed, in insertion order."""
        return [name for name in self._order if not self._tasks[name]]

    def get_completed_tasks(self):
        """Return the names of completed tasks, in insertion order."""
        return [name for name in self._order if self._tasks[name]]

    def __len__(self):
        """Return the total number of tasks held by the list."""
        return len(self._order)


def _normalize(task_name):
    """Validate a task name and return it stripped of surrounding whitespace."""
    if not isinstance(task_name, str):
        raise TypeError("task name must be a string, got {}".format(type(task_name).__name__))
    name = task_name.strip()
    if not name:
        raise ValueError("task name must not be empty")
    return name


def format_report(todo):
    """Render a to-do list as a multi-line human-readable report."""
    lines = ["To-do ({} task(s))".format(len(todo))]
    for name in todo.get_pending_tasks():
        lines.append("  [ ] {}".format(name))
    for name in todo.get_completed_tasks():
        lines.append("  [x] {}".format(name))
    if len(todo) == 0:
        lines.append("  (nothing to do)")
    return "\n".join(lines)


def build_list(names, completed=()):
    """Build a ToDoList from an iterable of names, completing those in `completed`."""
    todo = ToDoList()
    for name in names:
        todo.add_task(name)
    for name in completed:
        todo.mark_completed(name)
    return todo


def main():
    """Demonstrate the to-do list on a small set of chores."""
    todo = build_list(["Buy milk", "Walk dog", "Pay rent"], completed=["Buy milk"])
    print(format_report(todo))
    print("pending:", todo.get_pending_tasks())
    todo.mark_completed("Pay rent")
    print("pending after paying rent:", todo.get_pending_tasks())


if __name__ == "__main__":
    main()

