import math


def is_valid_sample(numbers):
    """
    Return True when every value is a positive, finite real number.

    An empty sample is not valid, since the geometric mean of no
    observations is undefined.
    """
    if not numbers:
        return False
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            return False
        if not math.isfinite(value) or value <= 0:
            return False
    return True


def exact_root(product, n):
    """
    Return the exact nth root of product when it is a whole number.

    Floating point powers such as 8.0 ** (1 / 3) come out slightly
    below the true root, so a whole-number candidate is verified by
    raising it back to the nth power. Returns None when no such root
    exists.
    """
    candidate = round(product ** (1.0 / n))
    if candidate > 0 and float(candidate) ** n == product:
        return float(candidate)
    return None


def geometric_mean(numbers):
    """
    Return the geometric mean of a list of positive numbers.

    The product is used directly when it stays finite, which keeps
    results such as 2.0 for [1, 2, 4] exact; otherwise logarithms
    avoid overflow. Returns 0.0 if the list is empty or holds any
    non-positive value.
    """
    if not is_valid_sample(numbers):
        return 0.0
    n = len(numbers)
    product = 1.0
    for value in numbers:
        product *= float(value)
    if math.isfinite(product) and product > 0.0:
        whole = exact_root(product, n)
        if whole is not None:
            return whole
        return product ** (1.0 / n)
    log_sum = math.fsum(math.log(float(value)) for value in numbers)
    return math.exp(log_sum / n)


def arithmetic_mean(numbers):
    """
    Return the ordinary average, or 0.0 for an empty list.
    """
    if not numbers:
        return 0.0
    return math.fsum(float(value) for value in numbers) / len(numbers)


def harmonic_mean(numbers):
    """
    Return the harmonic mean, or 0.0 when the sample is not positive.
    """
    if not is_valid_sample(numbers):
        return 0.0
    return len(numbers) / math.fsum(1.0 / float(value) for value in numbers)


def growth_rate(values):
    """
    Return the average period-over-period growth factor of a series.

    Consecutive ratios are combined geometrically, which is the correct
    way to average multiplicative changes. Needs at least two values.
    """
    if len(values) < 2:
        return 0.0
    ratios = []
    for previous, current in zip(values, values[1:]):
        if previous <= 0 or current <= 0:
            return 0.0
        ratios.append(current / previous)
    return geometric_mean(ratios)


def format_report(label, numbers):
    """
    Build a one-line summary of the three Pythagorean means.
    """
    return "{0:<16} A={1:.4f}  G={2:.4f}  H={3:.4f}".format(
        label,
        arithmetic_mean(numbers),
        geometric_mean(numbers),
        harmonic_mean(numbers),
    )


def main():
    """
    Print mean summaries for a few sample datasets.
    """
    samples = [
        ("powers of two", [1, 2, 4]),
        ("pair", [2, 8]),
        ("mixed floats", [1.5, 2.5, 6.0, 12.0]),
        ("has a zero", [3, 0, 9]),
        ("empty", []),
    ]
    for label, numbers in samples:
        print(format_report(label, numbers))

    revenue = [100.0, 115.0, 126.5, 151.8]
    print("mean growth factor: {0:.4f}".format(growth_rate(revenue)))


if __name__ == "__main__":
    main()

