def normalize_shift(length, n):
    """Reduce a rotation amount to the smallest equivalent right shift.

    Returns 0 for empty sequences so callers can rotate safely.
    """
    if length == 0:
        return 0
    return n % length


def rotate_list(lst, n):
    """Return a new list with the elements of ``lst`` rotated ``n`` places.

    Positive ``n`` rotates to the right, negative ``n`` to the left.
    """
    shift = normalize_shift(len(lst), n)
    if shift == 0:
        return list(lst)
    return lst[-shift:] + lst[:-shift]


def parse_shift(text):
    """Convert a textual rotation amount such as ``"-3"`` into an integer."""
    try:
        return int(text.strip())
    except ValueError:
        raise ValueError("rotation amount must be an integer, got " + repr(text))


def parse_items(text):
    """Split a comma separated string into a list of trimmed tokens."""
    if not text.strip():
        return []
    return [token.strip() for token in text.split(",")]


def format_list(items):
    """Render a list of items as a bracketed, comma separated string."""
    return "[" + ", ".join(str(item) for item in items) + "]"


def describe_rotation(lst, n):
    """Build a one line report of rotating ``lst`` by ``n`` positions."""
    direction = "right" if n >= 0 else "left"
    rotated = rotate_list(lst, n)
    return "{0} rotated {1} {2} -> {3}".format(
        format_list(lst), abs(n), direction, format_list(rotated)
    )


def rotate_request(line):
    """Handle one ``items | shift`` request line and return its report."""
    parts = line.rsplit("|", 1)
    if len(parts) != 2:
        raise ValueError("expected 'items | shift', got " + repr(line))
    return describe_rotation(parse_items(parts[0]), parse_shift(parts[1]))


def main(argv):
    """Rotate a list from the command line, or one request per input line."""
    if len(argv) == 2:
        print(describe_rotation(parse_items(argv[0]), parse_shift(argv[1])))
        return 0
    if argv:
        print("usage: rotate.py 'a, b, c' SHIFT")
        return 1

    import sys

    for line in sys.stdin:
        if line.strip():
            print(rotate_request(line))
    return 0


