def count_set_bits(n):
    """Return the number of '1' bits in the binary representation of n.

    Uses Kernighan's trick: clearing the lowest set bit once per iteration,
    so the loop runs exactly as many times as there are set bits.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count


def bit_length(n):
    """Return the number of bits needed to write n in base two (0 needs 1)."""
    return max(n.bit_length(), 1)


def binary_string(n, width=0):
    """Return n in base two, zero-padded on the left to at least `width` digits."""
    return format(n, "0%db" % max(width, 1))


def parse_number(text):
    """Convert a textual number to an int, accepting 0b/0o/0x prefixes.

    Underscores are allowed as digit separators, matching Python literals.
    """
    cleaned = text.strip().replace("_", "")
    if not cleaned:
        raise ValueError("empty numeric field")
    return int(cleaned, 0)


def parity(n):
    """Return 'even' or 'odd' according to the number of set bits in n."""
    return "odd" if count_set_bits(n) % 2 else "even"


def describe(n):
    """Build a one-line report about the set bits of n."""
    total = count_set_bits(n)
    return "%6d = %s : %d set bit%s (%s parity)" % (
        n,
        binary_string(n, bit_length(n)),
        total,
        "" if total == 1 else "s",
        parity(n),
    )


def report(texts):
    """Parse each text as a number and return the report lines for all of them."""
    lines = []
    for text in texts:
        lines.append(describe(parse_number(text)))
    return lines


def main(argv):
    """Report on the numbers given on the command line, or on a default sample."""
    arguments = argv[1:] or ["10", "7", "0", "255", "0b1011", "0xFF00"]
    for line in report(arguments):
        print(line)
    widest = max(count_set_bits(parse_number(t)) for t in arguments)
    print("maximum population count: %d" % widest)
    return 0


if __name__ == "__main__":
    import sys

    sys.exit(main(sys.argv))

