def is_prime(n):
    """
    Return True if n is a prime number, False otherwise.

    Numbers less than 2, including negatives and zero, are not prime.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("is_prime() expects an integer")
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True


def next_prime(n):
    """
    Return the smallest prime strictly greater than n.
    """
    candidate = max(n + 1, 2)
    while not is_prime(candidate):
        candidate += 1
    return candidate


def primes_up_to(limit):
    """
    Return the list of all primes p with p <= limit, using a sieve.
    """
    if limit < 2:
        return []
    flags = [True] * (limit + 1)
    flags[0] = flags[1] = False
    for base in range(2, int(limit ** 0.5) + 1):
        if flags[base]:
            for multiple in range(base * base, limit + 1, base):
                flags[multiple] = False
    return [value for value, prime in enumerate(flags) if prime]


def prime_factors(n):
    """
    Return the prime factors of n in ascending order, with repetition.
    """
    if n < 2:
        return []
    factors = []
    remainder = n
    factor = 2
    while factor * factor <= remainder:
        while remainder % factor == 0:
            factors.append(factor)
            remainder //= factor
        factor += 1 if factor == 2 else 2
    if remainder > 1:
        factors.append(remainder)
    return factors


def describe(n):
    """
    Return a human-readable one-line report about the integer n.
    """
    if is_prime(n):
        return "{0} is prime; the next prime is {1}.".format(n, next_prime(n))
    factorization = " * ".join(str(f) for f in prime_factors(n))
    if not factorization:
        return "{0} is not prime and has no prime factorization.".format(n)
    return "{0} is not prime: {0} = {1}.".format(n, factorization)


def main():
    """
    Report on a few sample integers and list the small primes.
    """
    for number in (1, 7, 10, 0, -5, 97, 360):
        print(describe(number))
    print("Primes up to 50:", primes_up_to(50))


if __name__ == "__main__":
    main()

