def simple_hash(s):
    """Return the sum of the ASCII (code point) values of every character in s.

    An empty string hashes to 0, so simple_hash('cat') == 99 + 97 + 116 == 312.
    """
    if not isinstance(s, str):
        raise TypeError("simple_hash expects a string, got %s" % type(s).__name__)
    return sum(ord(ch) for ch in s)


def hash_many(words):
    """Map each word in words to its simple_hash value, preserving order."""
    return [(word, simple_hash(word)) for word in words]


def bucket_index(s, table_size):
    """Return the slot of s in a hash table with table_size buckets."""
    if table_size <= 0:
        raise ValueError("table_size must be positive")
    return simple_hash(s) % table_size


def build_table(words, table_size):
    """Distribute words into table_size buckets keyed by bucket_index."""
    table = [[] for _ in range(table_size)]
    for word in words:
        table[bucket_index(word, table_size)].append(word)
    return table


def find_collisions(words):
    """Group words that share an identical simple_hash value.

    Returns a dict mapping the hash to the list of colliding words; words with
    a unique hash are left out of the result.
    """
    groups = {}
    for word, value in hash_many(words):
        groups.setdefault(value, []).append(word)
    return {value: group for value, group in groups.items() if len(group) > 1}


def format_hashes(words):
    """Render one 'word -> hash' line per word, aligned on the arrow."""
    pairs = hash_many(words)
    width = max((len(word) for word, _ in pairs), default=0)
    return "\n".join("%-*s -> %d" % (width, word, value) for word, value in pairs)


def format_table(table):
    """Render a bucket table as one line per slot, listing its contents."""
    lines = []
    for slot, contents in enumerate(table):
        lines.append("[%d] %s" % (slot, ", ".join(contents) if contents else "-"))
    return "\n".join(lines)


def main():
    """Hash a sample vocabulary and report hashes, buckets and collisions."""
    words = ["cat", "act", "tac", "dog", "bird", ""]
    print(format_hashes(words))
    print()
    print(format_table(build_table(words, 5)))
    print()
    collisions = find_collisions(words)
    if collisions:
        for value in sorted(collisions):
            print("collision at %d: %s" % (value, " ".join(collisions[value])))
    else:
        print("no collisions")


if __name__ == "__main__":
    main()

