import re

SIMULATED_FILES = {
    'dummy_file.txt': 'apple banana a',
    'empty.txt': '',
    'notes.txt': 'The quick brown fox jumps over 12 extraordinarily lazy dogs!',
    'mixed.txt': 'x86_64 arch, ipv6 addresses, and R2D2 units.',
}


def read_simulated_file(filepath):
    """Return the contents of a simulated file, or None when it does not exist."""
    return SIMULATED_FILES.get(filepath)


def extract_words(text):
    """Split text into alphanumeric word tokens, discarding punctuation and spaces."""
    return re.findall(r'[A-Za-z0-9]+', text)


def find_longest_word_in_file(filepath):
    """Return the longest alphanumeric word in the given file.

    An empty string is returned when the file is missing or contains no words.
    Ties are resolved in favour of the word that appears first.
    """
    contents = read_simulated_file(filepath)
    if contents is None:
        return ''
    longest = ''
    for word in extract_words(contents):
        if len(word) > len(longest):
            longest = word
    return longest


def word_length_histogram(filepath):
    """Map each word length found in a file to the number of words of that length."""
    contents = read_simulated_file(filepath)
    histogram = {}
    if contents is not None:
        for word in extract_words(contents):
            histogram[len(word)] = histogram.get(len(word), 0) + 1
    return histogram


def describe_file(filepath):
    """Build a one-line human readable summary of a file's longest word."""
    longest = find_longest_word_in_file(filepath)
    if not longest:
        return '{}: no words found'.format(filepath)
    count = word_length_histogram(filepath)[len(longest)]
    suffix = '' if count == 1 else ' (tied with {} other word(s))'.format(count - 1)
    return '{}: longest word is {!r} with {} characters{}'.format(
        filepath, longest, len(longest), suffix)


def report(filepaths):
    """Return summary lines for every requested path, in the order supplied."""
    return [describe_file(path) for path in filepaths]


def main():
    """Exercise the longest-word search over the simulated file set."""
    paths = ['dummy_file.txt', 'empty.txt', 'notes.txt', 'mixed.txt', 'missing.txt']
    for line in report(paths):
        print(line)


if __name__ == '__main__':
    main()

